-- Less Nova Halloween. New bootstrap; recovered modules do not run Luraph.
local RealEnv = getgenv and getgenv() or _G
if RealEnv.LessNovaCleanup then pcall(RealEnv.LessNovaCleanup) end
if RealEnv.LessV2Cleanup then pcall(RealEnv.LessV2Cleanup) end

local Services = setmetatable({}, { __index = function(self, name)
    local service = game:GetService(name); rawset(self, name, service); return service
end })
local Players, RunService, Http = Services.Players, Services.RunService, Services.HttpService
local LocalPlayer, Input, World = Players.LocalPlayer, Services.UserInputService, workspace
local Host = gethui and gethui() or Services.CoreGui
local alive, cleaning = true, false
local connections, finalizers, renderNames = {}, {}, {}
local instances = setmetatable({}, { __mode = "k" })
local threads = setmetatable({}, { __mode = "k" })
local diagnostics, moduleStatus = {}, {}
local Private = setmetatable({}, { __index = RealEnv })
local _G = Private
local function getgenv() return Private end
local RawTask = task
local task = {}
local function Alive() return alive end
local function recordError(name, message)
    local value = tostring(message)
    diagnostics[#diagnostics + 1] = { time = os.clock(), module = name, message = value }
    if #diagnostics > 100 then table.remove(diagnostics, 1) end
    warn("[Less Nova / " .. tostring(name) .. "] " .. value)
end
local function guarded(name, callback, ...)
    if not alive then return end
    local result = table.pack(pcall(callback, ...))
    if not result[1] then recordError(name, result[2]); return nil end
    return table.unpack(result, 2, result.n)
end
function task.spawn(callback, ...)
    if not alive then return nil end
    local args = table.pack(...)
    local thread = RawTask.spawn(function() guarded("task", callback, table.unpack(args, 1, args.n)) end)
    threads[thread] = true; return thread
end
function task.defer(callback, ...)
    if not alive then return nil end
    local args = table.pack(...)
    local thread = RawTask.defer(function() guarded("defer", callback, table.unpack(args, 1, args.n)) end)
    threads[thread] = true; return thread
end
function task.delay(seconds, callback, ...)
    if not alive then return nil end
    local args = table.pack(...)
    local thread = RawTask.delay(seconds, function() guarded("delay", callback, table.unpack(args, 1, args.n)) end)
    threads[thread] = true; return thread
end
task.wait, task.cancel, task.synchronize, task.desynchronize = RawTask.wait, RawTask.cancel, RawTask.synchronize, RawTask.desynchronize
local function New(class, parent)
    local object = Instance.new(class)
    instances[object] = true
    if parent then object.Parent = parent end
    return object
end
local function Make(class, properties, parent)
    local object = New(class)
    for key, value in pairs(properties or {}) do object[key] = value end
    if parent then object.Parent = parent end
    return object
end
local function Clone(object)
    local copy = object:Clone()
    if copy then instances[copy] = true end
    return copy
end
local function Connect(signal, callback)
    local lastError = -math.huge
    local connection = signal:Connect(function(...)
        if not alive then return end
        local ok, err = pcall(callback, ...)
        if not ok and os.clock() - lastError > 5 then lastError = os.clock(); recordError("event", err) end
    end)
    connections[#connections + 1] = connection
    return connection
end
local function OnCleanup(callback) finalizers[#finalizers + 1] = callback end
local function BindRender(name, priority, callback)
    local key = "LessNova/" .. name
    renderNames[name] = key
    local lastError=-math.huge
    RunService:BindToRenderStep(key, priority, function(dt)
        if alive then
            local ok,err=pcall(callback,dt)
            if not ok and os.clock()-lastError>5 then lastError=os.clock();recordError("render:"..name,err)end
        end
    end)
end
local function UnbindRender(name)
    RunService:UnbindFromRenderStep(renderNames[name] or "LessNova/" .. name)
    renderNames[name] = nil
end
local function Round(object, radius) return Make("UICorner", { CornerRadius = UDim.new(0, radius or 10) }, object) end
local function Stroke(object, color, thickness, transparency)
    return Make("UIStroke", { Color = color or Color3.new(1,1,1), Thickness = thickness or 1, Transparency = transparency or 0 }, object)
end
local function Tween(object, seconds, properties)
    local tween = Services.TweenService:Create(object, TweenInfo.new(seconds, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), properties)
    tween:Play(); return tween
end
local function getUpvalue(cell)
    if type(cell) == "table" and cell[1] and cell[3] ~= nil then return cell[1][cell[3]] end
    return cell
end
local function setUpvalue(cell, value)
    if type(cell) == "table" and cell[1] and cell[3] ~= nil then cell[1][cell[3]] = value end
    return value
end
local function isAlive(cell)
    local value = getUpvalue(cell)
    if type(value) == "function" then local ok, result = pcall(value); return ok and result ~= false and result ~= nil end
    return value ~= false and value ~= nil
end
local function PulseFC(object, name, recursive) return object and object:FindFirstChild(name, recursive) end
local function PulseFCC(object, class) return object and object:FindFirstChildOfClass(class) end
local UPPER = { Head=true, UpperTorso=true, Torso=true, LeftUpperArm=true, RightUpperArm=true,
    LeftLowerArm=true,RightLowerArm=true,LeftHand=true,RightHand=true,["Left Arm"]=true,["Right Arm"]=true }
local function PulsePlayers() return Players:GetPlayers() end
local function PULSE_NV(callback) return callback end
local Text = { lang = "en", data = {}, reg = {} }
function Text.tr(value) return value end
function Text.bind(object, value, property)
    if object then pcall(function() object[property or "Text"] = tostring(value or "") end) end
end
-- Compatibility is identity-only. No language dictionaries, switching or network translation.

local function clone(value)
    if type(value) ~= "table" then return value end
    local result = {}; for key, child in pairs(value) do result[key] = clone(child) end; return result
end
local function merge(target, value)
    for key, child in pairs(value or {}) do
        if type(child) == "table" and type(target[key]) == "table" then merge(target[key], child)
        else target[key] = clone(child) end
    end
end
