local function ensureFolders()
    if not makefolder then return end
    for _, path in ipairs({ "LessNova", "LessNova/configs", "LessNova/nova" }) do
        if not isfolder or not isfolder(path) then pcall(makefolder, path) end
    end
end
ensureFolders()
local function serial(value, seen)
    if typeof(value) == "Color3" then return { _type = "Color3", hex = value:ToHex() } end
    if typeof(value) == "EnumItem" then return { _type = "Enum", value = value.Name } end
    if type(value) ~= "table" then
        if type(value) == "string" or type(value) == "number" or type(value) == "boolean" then return value end
        return nil
    end
    seen = seen or {}; if seen[value] then return nil end; seen[value] = true
    local result = {}; for k, v in pairs(value) do if type(k) == "string" or type(k) == "number" then result[k] = serial(v, seen) end end
    seen[value] = nil; return result
end
local function decode(value)
    if type(value) ~= "table" then return value end
    if value._type == "Color3" then return Color3.fromHex(value.hex) end
    if value._type == "Enum" then return Enum.KeyCode[value.value] or Enum.UserInputType[value.value] end
    local result = {}; for k, v in pairs(value) do result[k] = decode(v) end; return result
end
local function readConfig(name)
    if not readfile or not isfile then return nil end
    local path = "LessNova/configs/" .. name .. ".json"
    if not isfile(path) then return nil end
    local ok, result = pcall(function() return decode(Http:JSONDecode(readfile(path))) end)
    if ok and type(result) == "table" then return result end
    return nil
end
local saved = readConfig("autosave")
if saved then merge(settings, saved.settings); stored = saved.controls or {} end
-- Aim FOV was a plain number before Pulse X. Accept both forms so old saves keep working.
if type(settings.sheriff) ~= "table" then settings.sheriff = {} end
do
    local fov = settings.sheriff.fov
    if type(fov) ~= "table" then
        fov = { on = true, size = math.clamp(tonumber(fov) or 180, 10, 1500) }
    else
        -- Pulse treats a missing "on" as disabled; only a saved number enables
        -- the limit automatically when migrating from older LessMM2 configs.
        fov.on = fov.on == true
        fov.size = math.clamp(tonumber(fov.size) or 180, 10, 1500)
    end
    settings.sheriff.fov = fov
end
if settings.sheriff.shotTiming == true then settings.sheriff.shotTiming = "Instant" end
-- HUD visibility never restores automatically on startup.
local persistedMobile = clone(settings.mobile.pos or {})
settings.mobile = {pos=persistedMobile}; settings.fly.on = false; settings.invis.on = false; settings.noclip.on = false
settings.spin.on = false; settings.bhop = false; settings.fakepos.on = false
settings.sheriff.autoShoot = false; settings.sheriff.silentAim = false
settings.sheriff.aimType = "Universal"
local function saveConfig(name)
    if not writefile then return false, "This environment does not support file writing." end
    ensureFolders()
    local payload = { version = 1, settings = serial(settings), controls = serial(stored) }
    payload.settings.mobile = {pos=serial(settings.mobile.pos or {})}
    local ok, err = pcall(writefile, "LessNova/configs/" .. name .. ".json", Http:JSONEncode(payload))
    return ok, err
end

-- Cached role reader adapted from Less: game role data, then weapon detection.
local roleCache, roleAt, roleBusy = {}, -math.huge, false
local function roles()
    if os.clock() - roleAt > 1 and not roleBusy then
        roleBusy = true
        task.spawn(function()
            local ok, data = pcall(function()
                local remote = Services.ReplicatedStorage:FindFirstChild("GetPlayerData", true)
                if remote and remote:IsA("RemoteFunction") then return remote:InvokeServer() end
                return nil
            end)
            if ok and type(data) == "table" then roleCache = data end
            roleAt = os.clock(); roleBusy = false
        end)
    end
    for _, player in ipairs(Players:GetPlayers()) do
        local char, bag = player.Character, player:FindFirstChildOfClass("Backpack")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local knife = (char and char:FindFirstChild("Knife")) or (bag and bag:FindFirstChild("Knife"))
        local gun = (char and char:FindFirstChild("Gun")) or (bag and bag:FindFirstChild("Gun"))
        local entry = roleCache[player.Name] or roleCache[player.UserId] or roleCache[tostring(player.UserId)] or {}
        if knife then entry.Role = "Murderer" elseif gun then entry.Role = entry.Role == "Sheriff" and "Sheriff" or "Hero"
        elseif not entry.Role then entry.Role = "Innocent" end
        entry.Dead = not hum or hum.Health <= 0
        roleCache[player.Name] = entry
    end
    return roleCache
end
local function rolePlayer(role)
    local data = roles()
    for _, player in ipairs(Players:GetPlayers()) do
        local entry = data[player.Name]
        if entry and not entry.Dead and (entry.Role == role or role == "Sheriff" and entry.Role == "Hero") then return player end
    end
end
Private.__pulseRoles = roles
Private.__pulseRolePlayer = rolePlayer
local function Root(player)
    local char = (player or LocalPlayer).Character
    return char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
end
local function Humanoid() return LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid") end
local function Equip(name)
    local char, bag, hum = LocalPlayer.Character, LocalPlayer:FindFirstChildOfClass("Backpack"), Humanoid()
    local tool = char and char:FindFirstChild(name)
    if not tool and bag and hum then
        tool = bag:FindFirstChild(name)
        if tool then hum:EquipTool(tool) end
    end
    return tool
end
