					function L:_applyBackground()
						local r = self.BgLayers
						if not r then
							return
						end
						local _, q = self.BgStyle, self.BgIntensity
						local function u(s)
							return math.clamp(1 - (1 - s) * q, 0, 1)
						end
						local q = _ == "Aurora"
						if r.meshA then
							r.meshA.ImageTransparency = u(q and 0.84 or 0.965)
						end
						if r.meshB then
							r.meshB.ImageTransparency = u(q and 0.9 or 0.975)
						end
						if r.auraA then
							r.auraA.ImageTransparency = u(q and 0.84 or 0.9)
						end
						if r.auraB then
							r.auraB.ImageTransparency = u(q and 0.9 or 0.94)
