								r.pattern.ScaleType = Enum.ScaleType.Tile
								local R = U.specs[q.tex]
								r.pattern.TileSize = UDim2.fromOffset(R.w, R.h)
								r.pattern.ImageTransparency = u(q.alpha)
							end
						else
							r.pattern.ImageTransparency = 1
						end
						if r.grain then
							r.grain.ImageTransparency = u(_ == "Noise" and 0.55 or 0.82)
						end
					end
					function L:SetBackground(R)
