		function w.cfg()
			if type(J.npc) ~= "table" then
				J.npc = {}
			end
			local V = J.npc
			if V.on == nil then
				V.on = true
			end
			if V.dances == nil then
				V.dances = true
			end
			if tonumber(V.volume) == nil then
				V.volume = 100
			end
			return V
		end
		function w.soundGroup()
			if w.sgrp and w.sgrp.Parent then
				return w.sgrp
			end
			local J = New("SoundGroup")
			J.Name = "PulseNpcSounds"
			J.Volume = math.clamp((tonumber(w.cfg().volume) or 100) / 100, 0, 1)
			J.Parent = game:GetService("SoundService")
			w.sgrp = J
			return J
		end
		function w.setVolume(J)
			w.cfg().volume = math.clamp(tonumber(J) or 100, 0, 100)
			pcall(function()
				w.soundGroup().Volume = w.cfg().volume / 100
			end)
		end
