		function w.songReady(X)
			if X.data and not X.asset then
				return false
			end
			for c, c in ipairs(X.tracks or {}) do
				if not c.asset then
					return false
				end
			end
			return true
		end
		function w.prepSongs()
			if w.prepBusy then
				return
			end
			w.prepBusy = true
			task.spawn(function()
				for X, X in ipairs(w.SONGS) do
					if X.data and not X.asset then
						pcall(w.trackAsset, X)
					end
					for c, c in ipairs(X.tracks or {}) do
						if not c.asset then
							c.asset = w.fileAsset(c.file, c.data)
						end
					end
				end
				if not w.tvNoise then
					w.tvNoise = w.fileAsset("LessNova/tv_noise_v1.png", w.TVNOISE)
				end
				w.prepBusy = false
			end)
		end
		function w.trackAsset(X)
			if X.asset then
				return X.asset
			end
			if not X.data then
				return false
			end
			X.asset = w.fileAsset(X.file, X.data)
			return X.asset or false
		end
		function w.joints()
			if w.jm and w.jmModel == w.model then
				return w.jm
			end
			local X = {}
			for c, c in ipairs(w.model and w.model:GetDescendants() or {}) do
				if c:IsA("AnimationConstraint") or c:IsA("Motor6D") then
					X[c.Name] = c
				end
			end
			w.jm, w.jmModel = X, w.model
			return X
		end
		local function X(c)
			c = math.clamp(c, 0, 1)
			return c * c * (3 - 2 * c)
		end
		local function c(K, V, r, _, q)
			_, q = _ or 0.12, q or 0.15
			if K <= V - _ or K >= r + q then
				return 0
			end
			if K < V then
				return X((K - V + _) / _)
			end
			if K > r then
				return 1 - X((K - r) / q)
			end
			return 1
		end
		local function K(V, r, _)
