			_.matSet, _.matMade, _.matPrev = "Game", {}, {}
			_.setMaterials = function(s)
				if s == _.matSet then
					return
				end
				for h, Y in pairs(_.matPrev) do
					pcall(function()
						q:SetBaseMaterialOverride(Enum.Material[h], Y)
					end)
				end
				_.matPrev = {}
				for h, h in ipairs(_.matMade) do
					pcall(function()
						h:Destroy()
					end)
				end
				_.matMade = {}
				local h = u[s]
				if h then
					for u, Y in pairs(h) do
						pcall(function()
							local l = New("MaterialVariant")
							l.Name = "PulseHD_" .. u
							l.BaseMaterial = Enum.Material[u]
							if Y[1] ~= "" then
								l.ColorMap = "rbxassetid://" .. Y[1]
							end
							if Y[2] ~= "" then
								l.NormalMap = "rbxassetid://" .. Y[2]
							end
							if Y[3] ~= "" then
								l.RoughnessMap = "rbxassetid://" .. Y[3]
							end
							if Y[4] ~= "" then
								l.MetalnessMap = "rbxassetid://" .. Y[4]
							end
							l.StudsPerTile = Y[5]
							l.Parent = q
							_.matMade[#_.matMade + 1] = l
							_.matPrev[u] = q:GetBaseMaterialOverride(Enum.Material[u])
							q:SetBaseMaterialOverride(Enum.Material[u], l.Name)
						end)
					end
				end
				_.matSet = h and s or "Game"
			end
			_.neonLights = {}
			_.lampScan = function()
				local q = _.mapRoots()
				local u = _.lampRoots ~= nil and #_.lampRoots == #q
				if u then
					for s, h in ipairs(q) do
						if _.lampRoots[s] ~= h then
							u = false
							break
						end
					end
				end
				local s = os.clock()
				if u and s < (_.lampScanAt or 0) then
					return
				end
				_.lampScanAt = s + (u and 30 or 5)
				_.lampRoots, _.lamps, _.neons = q, {}, {}
				for u, u in ipairs(q) do
					for q, q in ipairs(u:GetDescendants()) do
						local u = q.ClassName
						if u == "PointLight" or u == "SpotLight" or u == "SurfaceLight" then
							if not _.owned[q] and q.Name ~= "PulseNeonGlow" then
								_.lamps[#_.lamps + 1] = q
							end
						elseif q:IsA("BasePart") and q.Material == Enum.Material.Neon and q.Transparency < 0.6 then
							_.neons[#_.neons + 1] = q
						end
					end
				end
			end
			_.lampApply = function()
				local q = tonumber(_.lampBoost) or 1
				local u = _.on and math.abs(q - 1) > 0.01
				if u or _.on and _.neonGlow then
					pcall(_.lampScan)
				end
				for s, s in ipairs(_.lamps or {}) do
					if s.Parent then
						local h = u and _.baseline(s, "Brightness")
						_.sync(s, "Brightness", u, (tonumber(h) or 1) * q)
						local h = u and _.baseline(s, "Range")
						_.sync(s, "Range", u, math.min(60, (tonumber(h) or 8) * (1 + (q - 1) * 0.5)))
					end
				end
				for q, u in pairs(_.neonLights) do
					if not q.Parent or not u.Parent then
						pcall(function()
							u:Destroy()
						end)
						_.neonLights[q] = nil
					end
				end
				if _.on and _.neonGlow then
					local q = 0
					for u in pairs(_.neonLights) do
						q += 1
					end
					for u, u in ipairs(_.neons or {}) do
						if q >= 90 then
							break
						end
						if u.Parent and not _.neonLights[u] then
							local s = u.Size
							local h = math.max(s.X, s.Y, s.Z)
							if h >= 0.8 then
								pcall(function()
									local s = New("PointLight")
									s.Name = "PulseNeonGlow"
									s.Color = u.Color
									s.Brightness = 1.4
									s.Range = math.clamp(h * 1.6, 6, 18)
									s.Shadows = false
									s.Parent = u
									_.owned[s] = true
									_.neonLights[u] = s
									q += 1
								end)
							end
						end
					end
				else
					for q, u in pairs(_.neonLights) do
						pcall(function()
							u:Destroy()
						end)
						_.neonLights[q] = nil
					end
				end
			end
