				if _.packAsset == nil then
					_.packAsset = false
					pcall(function()
						if type(writefile) ~= "function" or type(getcustomasset) ~= "function" then
							return
						end
						if
							type(isfolder) == "function"
							and type(makefolder) == "function"
							and not isfolder("LessNova")
						then
							makefolder("LessNova")
						end
						if not (type(isfile) == "function" and isfile("LessNova/shader_packs_v3.jpg")) then
							writefile("LessNova/shader_packs_v3.jpg", F(_.PACK_ATLAS))
						end
						local q = getcustomasset("LessNova/shader_packs_v3.jpg")
						if type(q) == "string" and #q > 0 then
							_.packAsset = q
						end
					end)
				end
				if not _.packAsset then
					return
				end
				for q, u in ipairs(_.packTiles or {}) do
					u.img.Image = _.packAsset
					u.img.ImageRectOffset = Vector2.new((q - 1) % 4 * 256, math.floor((q - 1) / 4) * 128)
					u.img.ImageRectSize = Vector2.new(256, 128)
					u.img.Visible = true
				end
			end
			_.applyExtras = function(q)
				local u = rawget(getgenv(), "__pulseWeather")
				if type(u) ~= "table" or type(u.settingsChanged) ~= "function" then
					return
				end
				local s = _.extras[q]
				if not s then
					if _.extrasOn then
						_.extrasOn = false
						u.scene = ""
						u.on = false
						pcall(u.settingsChanged)
						if _.extrasSky and u.setSky then
							pcall(u.setSky, nil)
						end
						_.extrasSky = nil
						if u.syncUI then
							pcall(u.syncUI)
						end
						if u.paintScenes then
							pcall(u.paintScenes)
						end
					end
					return
				end
				pcall(u.stop)
				local q = {
					quality = true,
					shelter = true,
					sound = true,
					soundVolume = true,
					wet = true,
					wetness = true,
					grade = true,
					matchLight = true,
					radius = true,
					scale = true,
					ripples = true,
					gusts = true,
