				for h, Y in pairs(u.defaults or {}) do
					if not q[h] and not string.find(h, "olour", 1, true) then
						u[h] = Y
					end
				end
				u.scene = ""
				if s.weather then
					u.on = true
					for q, h in pairs(s.weather) do
						u[q] = h
					end
				else
					u.on = false
				end
				pcall(u.settingsChanged)
				if s.sky and u.setSky then
					pcall(u.setSky, s.sky)
					_.extrasSky = s.sky
				end
				_.extrasOn = true
				if u.syncUI then
					pcall(u.syncUI)
				end
				if u.paintScenes then
					pcall(u.paintScenes)
				end
			end
			_.nextPreset = function()
				local q = _.presetNames()
				local u = 1
				for s, h in ipairs(q) do
					if h == _.preset then
