			R.number = function(r, q, u, s)
				r = tonumber(r)
				if r == nil or r ~= r or r == math.huge or r == -math.huge then
					r = q
				end
				return math.clamp(r, u, s)
			end
			R.validate = function()
				if R.recipes[R.kind] == nil then
					R.kind = "Snow"
				end
				if R.qualities[R.quality] == nil then
					R.quality = "Balanced"
				end
				for r, q in pairs(R.limits) do
					R[r] = R.number(R[r], q[1], q[2], q[3])
				end
				for r, r in ipairs(R.colourFields) do
					if typeof(R[r]) ~= "Color3" then
						R[r] = R.defaults[r]
					end
				end
			end
			R.mapRoots = function()
				local r = os.clock()
				if R.rootsAt and r - R.rootsAt < 5 and R.roots then
					return R.roots
				end
				local q = {}
				for u, u in ipairs(workspace:GetChildren()) do
					if
						u.ClassName == "Model"
						and (u:FindFirstChild("CoinContainer") or string.find(u.Name, "Lobby", 1, true))
					then
						q[#q + 1] = u
					end
				end
				R.roots, R.rootsAt = q, r
				return q
			end
			R.invisible = setmetatable({}, { __mode = "k" })
			R.splashes = {}
			R.filter = function(r)
				local q = { r }
				for r, r in ipairs(game:GetService("Players"):GetPlayers()) do
					if r.Character then
						q[#q + 1] = r.Character
					end
				end
				for r in pairs(R.invisible) do
					if r.Parent then
						q[#q + 1] = r
					end
				end
				local r = RaycastParams.new()
				r.FilterType = Enum.RaycastFilterType.Exclude
				r.FilterDescendantsInstances = q
				r.IgnoreWater = true
				pcall(function()
					r.RespectCanCollide = true
				end)
				R.params = r
			end
			R.cast = function(r, q)
				if not R.params then
					return nil, false
				end
				for u = 1, 6 do
					local u, s = pcall(function()
						return workspace:Raycast(r, q, R.params)
					end)
					if not u then
						return nil, false
					end
					if not s then
						return nil, true
					end
					local r = s.Instance
					if r:IsA("BasePart") and r.Transparency >= 0.95 then
						R.invisible[r] = true
						pcall(function()
							R.params:AddToFilter(r)
						end)
					else
						return s, true
					end
				end
				return nil, true
			end
			R.volume = function(r, q)
				local u = New("Part")
				u.Name = q
				u.Anchored, u.CanCollide, u.CanTouch, u.CanQuery = true, false, false, false
				u.CastShadow, u.Transparency = false, 1
				u.Size = Vector3.new(1, 1, 1)
				u.Parent = r
				return u
			end
			R.clear = function()
				for r, r in ipairs(R.nodes) do
					pcall(function()
						r.emitter:Clear()
					end)
				end
				for r, r in ipairs(R.splashes) do
					pcall(function()
						r.ripple:Clear()
						r.spray:Clear()
					end)
				end
			end
			R.stop = function(r)
				if not r then
					R.wetLevel, R.wetPainted = 0, 0
					pcall(R.wetRestore)
				end
				if R.folder then
					pcall(function()
						R.folder:Destroy()
					end)
				end
				if R.flash then
					pcall(function()
						R.flash:Destroy()
					end)
				end
				if R.gradeFx then
					pcall(function()
						R.gradeFx:Destroy()
					end)
				end
				R.folder, R.flash, R.gradeFx, R.camera, R.character, R.lastPosition, R.params =
					nil, nil, nil, nil, nil, nil, nil
				R.builtKind, R.builtQuality, R.builtSound, R.boltPart, R.storm = nil, nil, nil, nil, nil
				table.clear(R.nodes)
				R.splashes = {}
				table.clear(R.voices)
				R.splashIndex, R.splashBudget = 0, 0
				R.visibility, R.frameElapsed, R.probeElapsed = 0, 0, 1
				R.cameraCovered, R.suspended, R.dirty = nil, nil, true
				R.audioLevel, R.gradeLevel, R.coverBlend = 0, 0, 0
			end
			R.destroy = function()
				R.stop()
				R.dead = true
			end
			R.envStep = function()
				local r = game:GetService("Lighting")
				local q = r.ClockTime
				local u = math.clamp((q - 5.5) / 1.5, 0, 1) * math.clamp((19.5 - q) / 1.5, 0, 1)
				local q = r.OutdoorAmbient
				local r = (q.R + q.G + q.B) / 3
				local q = math.clamp(1 - r / 0.55, 0, 1)
				R.envDark = math.max(1 - u, q * 0.8)
			end
			R.audioBuild = function()
				table.clear(R.voices)
				R.audioLevel = 0
				if not R.sound then
					return
				end
				for r, r in ipairs(R.recipes[R.kind].voices or {}) do
					local q = New("Sound")
					q.Name = "Voice"
					q.SoundId = r.id
					q.Looped, q.Volume = true, 0
					q.RollOffMode = Enum.RollOffMode.Linear
					q.Parent = R.folder
					local u = New("EqualizerSoundEffect")
					u.LowGain, u.MidGain, u.HighGain = 0, 0, 0
					u.Parent = q
					pcall(function()
						q:Play()
					end)
