				local u, s
				if q < 0.12 then
					u, s = "close", 110 + math.random() * 90
				elseif q < 0.55 then
					u, s = "mid", 260 + math.random() * 260
				else
					u, s = "far", 560 + math.random() * 420
				end
				local q = R.camera.CFrame.LookVector
				local h = math.atan2(q.Z, q.X)
				h = math.random() < 0.6 and h + (math.random() - 0.5) * 1.6 or math.random() * 3.141592653589793 * 2
				local q = T + Vector3.new(math.cos(h) * s, -6.0, math.sin(h) * s)
				local T = q
					+ Vector3.new((math.random() - 0.5) * s * 0.15, 130 + s * 0.55, (math.random() - 0.5) * s * 0.15)
				local h = (T - q).Magnitude
				local Y = h * 0.045
				local function l(x, S, k, y)
					local Q = { x }
					for E = 1, k - 1 do
						local I = E / k
						Q[#Q + 1] = x:Lerp(S, I)
							+ Vector3.new(
								(math.random() - 0.5) * 2 * y * (1 - I * 0.3),
								(math.random() - 0.5) * y * 0.4,
								(math.random() - 0.5) * 2 * y * (1 - I * 0.3)
