local UI = { Nova = Nova, W = Window, gui = Window.Gui, NovaTabs = {}, tabs = {}, _tabList = {}, _ckeys = {}, dead = false }
local controlsByTab = {}
local route = { NovaSectionIcons = {} }
function route.novaResolve(tab, sub, title)
    local native = UI.NovaTabs[tab]
    if native and sub and native.SubDefs and not (native.SubButtons and native.SubButtons[sub]) then
        local defs = {}; for _, d in ipairs(native.SubDefs) do defs[#defs + 1] = d end
        defs[#defs + 1] = { key = sub, label = sub, icon = "sparkles" }
        native:SubTabs(defs)
    end
    return tab, sub, title ~= "*" and title or nil
end
local paletteMap = { accent = "Accent", bg = "Background", card = "Surface", card2 = "Surface2", text = "Text", muted = "Muted", line = "Line", danger = "Danger" }
UI.Slate = { Theme = setmetatable({ refreshHooks = config.refreshHooks, accent = Color3.fromHex("FF8B26") }, {
    __index = function(_, key) return Nova.Theme.resolve(paletteMap[key] or "Muted") end,
}) }
local adaptTab = Modules["VM.M"]({
    [0] = Round, [1] = Make, [2] = controlDefaults, [3] = setters, [4] = Text,
    [5] = stored, [6] = route, [7] = Connect, [8] = LocalPlayer, [9] = Alive, [10] = {},
})
function UI:Tab(name, icon)
    if controlsByTab[name] then return controlsByTab[name] end
    local tab = adaptTab(self, name, icon, self)
    function tab:Input(def)
        local key=name.."/Input/"..tostring(def.Text)
        local value=stored[key] or def.Default or ""
        local section=self:LastSection()
        if not section then self:Header("General");section=self:LastSection() end
        local function changed(nextValue)
            value=tostring(nextValue or "");stored[key]=value
            if def.Callback then def.Callback(value) end
        end
        local native=section:Input({Text=def.Text,Default=value,Placeholder=def.Placeholder,Callback=changed})
        controlDefaults[key]=def.Default or ""
        -- Expose the native box for focused, feature-specific styling (for example,
        -- the visual-skins search box needs a high-contrast text treatment).
        local handle={Row=native.Row,Box=native.Box,Get=function()return value end}
        handle.Set=function(a,b)
            local nextValue=a==handle and b or a
            native:Set(nextValue);changed(nextValue)
        end
        setters[key]=function(v)handle.Set(v)end
        changed(value)
        return handle
    end
    controlsByTab[name] = tab; return tab
end
