Private.__pulseData = { take = function(name)
    if name == "skins_db" then
        local ok, result = pcall(function()
            local sync = require(Services.ReplicatedStorage.Database.Sync)
            local items = sync.Item or sync.Items or sync.Weapons or {}
            return Http:JSONEncode(serial(items))
        end)
        if ok then return result end
    end
    return nil -- Missing encrypted asset payloads are replaced by local addons.
end }

local b64alphabet = {}; for i = 1, 64 do b64alphabet[string.byte("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", i)] = i - 1 end
local Base64 = Modules.U({ [0] = b64alphabet })
local function SafeInit(callback)
    local ok, err = pcall(callback)
    if not ok then recordError("subsystem", err) end
    return ok
end
local function Start(name, env, key)
    local beforeErrors=#diagnostics
    local ok, err = pcall(function()
        local init = assert(Modules[key or name], "Factory missing: " .. tostring(key or name))(env)
        if type(init) == "function" then init() end
    end)
    local partial=ok and #diagnostics>beforeErrors
    moduleStatus[name] = { ok = ok and not partial, partial=partial, error = not ok and tostring(err) or partial and "One or more subsystems reported an error." or nil }
    if not ok then recordError(name, err) end
    return ok
end
