local less = { lastShot = -math.huge, lastThrow = -math.huge, lastGrab = -math.huge }
local function Visible(target, origin)
    if not target then return false end
    local root, myRoot = Root(target), Root()
    if not root or not myRoot then return false end
    local ray = RaycastParams.new(); ray.FilterType = Enum.RaycastFilterType.Exclude
    ray.FilterDescendantsInstances = { LocalPlayer.Character, target.Character, Window.Gui }
    local from = origin or myRoot.Position
    return World:Raycast(from, root.Position - from, ray) == nil
end
function less.shoot()
    if os.clock() - less.lastShot < 0.35 then return false end
    local target = rolePlayer("Murderer"); local root, myRoot = Root(target), Root()
    if not target or target == LocalPlayer or not root or not myRoot then return false end
    if (root.Position - myRoot.Position).Magnitude > 300 then return false end
    if not settings.sheriff.wallbang and not Visible(target) then return false end
    local gun = Equip("Gun"); local remote = gun and gun:FindFirstChild("Shoot")
    if not remote or not remote:IsA("RemoteEvent") then return false end
    local origin = myRoot:FindFirstChild("GunRaycastAttachment")
    local start = origin and origin.WorldCFrame or myRoot.CFrame
    local lead = math.clamp(LocalPlayer:GetNetworkPing() + 0.06 + settings.sheriff.predEx, 0, 0.5)
    local position = root.Position + root.AssemblyLinearVelocity * lead
    remote:FireServer(start, CFrame.new(position)); less.lastShot = os.clock(); return true
end
function less.grab()
    if os.clock() - less.lastGrab < 0.5 then return false end
    local character = LocalPlayer.Character
    local backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
    if character and character:FindFirstChild("Gun") or backpack and backpack:FindFirstChild("Gun") then return false end
    local root = Root(); if not root or type(firetouchinterest) ~= "function" then return false end
    local drop, part
    for _, candidate in ipairs(World:GetDescendants()) do
        if candidate.Name == "GunDrop" and candidate.Parent then
            local firstPart, touchPart
            local function inspect(item)
                if not item:IsA("BasePart") then return end
                firstPart = firstPart or item
                if item:FindFirstChild("TouchInterest") or item:FindFirstChildOfClass("TouchTransmitter") then
                    touchPart = touchPart or item
                end
            end
            inspect(candidate)
            for _, item in ipairs(candidate:GetDescendants()) do inspect(item) end
            part = touchPart or firstPart
            if part then drop = candidate; break end
        end
    end
    if not (drop and part) then return false end
    less.lastGrab = os.clock()
    for attempt = 1, 5 do
        if not (drop.Parent and part.Parent) then break end
        pcall(function()
            firetouchinterest(root, part, 0)
            firetouchinterest(root, part, 1)
        end)
        task.wait(0.05)
        character = LocalPlayer.Character
        backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
        if character and character:FindFirstChild("Gun") or backpack and backpack:FindFirstChild("Gun") then
            return true
        end
    end
    return false
end
function less.throw()
    if os.clock() - less.lastThrow < 1 then return false end
    local myRoot = Root(); if not myRoot then return false end
    local nearest, distance
    for _, player in ipairs(Players:GetPlayers()) do
        local root = Root(player)
        if player ~= LocalPlayer and root and (settings.sheriff.wallbang or Visible(player)) then
            local d = (root.Position - myRoot.Position).Magnitude
            if not distance or d < distance then nearest, distance = root, d end
        end
    end
    local knife = Equip("Knife")
    local remote = knife and (knife:FindFirstChild("Throw") or knife:FindFirstChild("KnifeThrown", true))
    if not nearest or not remote or not remote:IsA("RemoteEvent") then return false end
    remote:FireServer(myRoot.CFrame, CFrame.new(nearest.Position + nearest.AssemblyLinearVelocity * 0.1))
    less.lastThrow = os.clock(); return true
end
Private.__pulseShotMurder, Private.__pulseThrowKnife = less.shoot, less.throw

