-- Keep Less actions as fallback when an advanced Pulse primitive is unavailable.
local advancedShoot, advancedGrab, advancedThrow = Private.__pulseShotMurder, Private.__pulsePickUpGun, Private.__pulseThrowKnife
Private.__pulseShotMurder = function()
    if moduleStatus.aim.ok and advancedShoot ~= less.shoot then
        local ok, result = pcall(advancedShoot)
        if ok and result then return result end
    end
    return less.shoot()
end
Private.__pulseThrowKnife = function()
    if moduleStatus.knife.ok and advancedThrow ~= less.throw then
        local ok, result = pcall(advancedThrow)
        if ok and result then return result end
    end
    return less.throw()
end
Private.__pulsePickUpGun = function(...)
    if moduleStatus.aim.ok and advancedGrab and advancedGrab ~= less.grab then
        local ok, result = pcall(advancedGrab, ...)
        if ok and result then return result end
    end
    return less.grab(...)
end

