Combat:Slider({ Text="Aim FOV", Min=10, Max=1500, Default=fov.size, Decimals=0, Callback=function(v)fovSettings().size=v end })
Combat:Slider({ Text="Prediction extra", Min=0, Max=0.5, Default=settings.sheriff.predEx, Decimals=2, Callback=function(v)settings.sheriff.predEx=v end })
Combat:Slider({ Text="Flick Speed", Min=1, Max=12, Default=settings.sheriff.flickSpeed or 6, Decimals=1, Callback=function(v)settings.sheriff.flickSpeed=v end })
Combat:Slider({ Text="Flick Return", Min=0, Max=100, Default=settings.sheriff.flickReturn or 100, Decimals=0, Callback=function(v)settings.sheriff.flickReturn=v end })
Combat:Toggle({ Text = "Flick Mouse", Default=settings.sheriff.flickMouse ~= false, Callback=function(v) settings.sheriff.flickMouse=v end })
Combat:Dropdown({ Text="Shot Timing", Default=(settings.sheriff.shotTiming == "Instant" or settings.sheriff.shotTiming == true) and "Instant" or "Off", Options={{code="Off",label="Off"},{code="Instant",label="Instant"}}, Callback=function(v)
    settings.sheriff.shotTiming = v == "Instant" and "Instant" or false
