Combat:Toggle({ Text = "PBlank", Default=false, Callback=function(v) settings.sheriff.pblank=v end })
local nextCoreStep = 0
Connect(RunService.Heartbeat, function()
    if os.clock() < nextCoreStep then return end; nextCoreStep=os.clock()+0.1
    if settings.sheriff.autoShoot and not moduleStatus.aim.ok then less.shoot() end
    if settings.sheriff.autoGun and not moduleStatus.aim.ok then Private.__pulsePickUpGun() end
    if settings.antiFling and Root() then
        local root=Root()
        if root.AssemblyLinearVelocity.Magnitude>180 then root.AssemblyLinearVelocity=Vector3.zero;root.AssemblyAngularVelocity=Vector3.zero end
    end
end)

-- Local configuration UI only; no community/config/cloud service is included.
local Settings = UI:Tab("Settings", "settings")
Settings:Header("Interface")
Window:AddAppearance(Settings.Native, { SkipKey=false })
Settings:Slider({Text="Screen Stretch",Min=0,Max=35,Default=settings.ui.stretch,Decimals=0,Callback=function(v)settings.ui.stretch=math.clamp(tonumber(v)or 0,0,35)end})
BindRender("ScreenStretch",Enum.RenderPriority.Last.Value,function()
    local cam=World.CurrentCamera
    if cam and settings.ui.stretch>0 then
        cam.CFrame=cam.CFrame*CFrame.new(0,0,0,1+settings.ui.stretch/100,0,0,0,1,0,0,0,1)
    end
end)
local function applyConfig(data, startup)
    if type(data)~="table" then return false end
    config.applying=true
    if data.settings then merge(settings,data.settings) end
    settings.ui=settings.ui or {}
    settings.ui.stretch=math.clamp(tonumber(settings.ui.stretch)or 0,0,35)
    if type(settings.sheriff) ~= "table" then settings.sheriff = {} end
    if settings.sheriff.shotTiming == true then settings.sheriff.shotTiming = "Instant" end
    fovSettings()
    local aim = getgenv().__pulseAim
    if aim then
        aim.on = aimHookEnabled()
        if aim.on and aim.installHook then pcall(aim.installHook) end
    end
    local aimx = getgenv().__pulseAimX
    if aimx and aimx.applyTiming then pcall(aimx.applyTiming) end
    for key,value in pairs(settings.mobile) do if type(value)=="boolean" then settings.mobile[key]=false end end
    for key,value in pairs(data.controls or {}) do
        if not (tostring(key):match("^Buttons/") and tostring(key):match(" Button#?%d*$")) then
            local setter=setters[key]
            if setter then guarded("config:"..key,setter,value) else stored[key]=value end
        end
    end
    for _,callback in ipairs(config.applyHooks) do guarded("apply_config",callback) end
    if Private.__pulseSyncUIS then Private.__pulseSyncUIS() end
    config.applying=false
    return true
end
Settings:Header("Local configurations")
local configName="personal"
Settings:Input({Text="Config name",Default=configName,Placeholder="personal",Callback=function(value)configName=tostring(value):gsub("[^%w_-]",""):sub(1,40) end})
Settings:Button({Text="Save local config",Callback=function()
    if configName=="" then Notify("Enter a name.");return end
    local ok,err=saveConfig(configName);Notify(ok and "Configuration saved." or tostring(err))
end})
Settings:Button({Text="Load local config",Callback=function()
    local data=readConfig(configName)
    if data then applyConfig(data);Notify("Configuration loaded. Buttons remain hidden until enabled.") else Notify("Configuration not found.") end
end})
Settings:Button({Text="Delete local config",Callback=function()
    if configName=="" or configName=="autosave" then Notify("Choose a named configuration first.");return end
    if delfile and isfile and isfile("LessNova/configs/"..configName..".json") then
        delfile("LessNova/configs/"..configName..".json");Notify("Configuration deleted.")
    end
end})
Settings:Button({Text="Reset settings",Callback=function()
    local values={};for key,value in pairs(controlDefaults) do values[key]=clone(value) end
    applyConfig({settings=defaults,controls=values})
    for _,callback in ipairs(Private.__pulseResetHooks) do guarded("reset",callback) end
    Notify("Valores predeterminados restaurados.")
end})
Settings:Header("Diagnostics")
Settings:Button({Text="Show module status",Callback=function()
    local rows={}
    for name,status in pairs(moduleStatus) do rows[#rows+1]=(status.ok and "OK " or "ERROR ")..name end
    table.sort(rows);Notify(table.concat(rows,"\n"),"Modules")
end})
Settings:Button({Text="Save diagnostics locally",Callback=function()
    if writefile then writefile("LessNova/diagnostics.json",Http:JSONEncode({modules=moduleStatus,errors=diagnostics}));Notify("Saved to LessNova/diagnostics.json") end
end})
local function Cleanup()
    if cleaning then return end;cleaning=true
    pcall(saveConfig,"autosave")
    alive=false;UI.dead=true
    for name in pairs(renderNames) do pcall(UnbindRender,name) end
    for _,connection in ipairs(connections) do pcall(function()connection:Disconnect()end) end
    for i=#finalizers,1,-1 do pcall(finalizers[i]) end
    local current=coroutine.running()
    for thread in pairs(threads) do if thread~=current then pcall(RawTask.cancel,thread) end end
    pcall(function()Window:Destroy()end)
    for instance in pairs(instances) do pcall(function()instance:Destroy()end) end
    if RealEnv.LessNovaCleanup==Cleanup then RealEnv.LessNovaCleanup=nil end
end
RealEnv.LessNovaCleanup=Cleanup
Settings:Button({Text="Unload Less MM2",Callback=Cleanup})
-- Additional standalone features are installed below.


-- Original Less visual weapon engine, with tracked resources.
do
local function CreateLessSkins(forceRefresh)
		-- The menu uses 2D catalog art; the equipped weapon still uses the Less model overlay.
		local previewOnly2D = false
		local Players_ = game:GetService("Players")
		local ReplicatedStorage_ = game:GetService("ReplicatedStorage")
		game:GetService("InsertService")
		local localPlayer2 = Players_.LocalPlayer

		pcall(function()
			if setthreadidentity then
				setthreadidentity(2)
			end
		end)

		if _G.__MM2Viz and _G.__MM2Viz.destroy then
			pcall(_G.__MM2Viz.destroy)
		end

		local mM2Viz = { conns = {} }
		_G.__MM2Viz = mM2Viz
		local EquipService = require(ReplicatedStorage_:WaitForChild("ClientServices"):WaitForChild("EquipService"))
		local Sync = require(ReplicatedStorage_:WaitForChild("Database"):WaitForChild("Sync"))
		local ProfileData = require(ReplicatedStorage_:WaitForChild("Modules"):WaitForChild("ProfileData"))
		local weapons = Sync.Weapons
		local inventoryDataChanged = ReplicatedStorage_:WaitForChild("Remotes"):WaitForChild("Inventory"):WaitForChild("InventoryDataChanged")

		local function fn59(arg)
			local ok, result = pcall(function()
				return game:HttpGet(arg, true)
			end)

			if ok and type(result) == "string" and #result > 0 then
				return result
			end
			local request_ = syn and syn.request or request or http_request or http and http.request
			if not request_ then
				return nil, tostring(result)
			end
			local ok2, result2 = pcall(request_, { Url = arg, Method = "GET" })
			if ok2 and type(result2) == "table" and type(result2.Body) == "string" and #result2.Body > 0 then
				return result2.Body
			end
			return nil, tostring(ok2 and result2 and result2.StatusCode or result2)
		end

		local lua = nil
		local cachedLua = nil

		if isfile and readfile and isfile("LessV2/weapon.lua") then
			local ok, result = pcall(readfile, "LessV2/weapon.lua")

			if ok and type(result) == "string" and #result > 100000 then
				cachedLua = result
				if not forceRefresh then lua = result end
			end
		end

		local flag16 = lua ~= nil
		local v11 = nil

		if forceRefresh or not lua then
			local downloaded
			downloaded, v11 = fn59("https://raw.githubusercontent.com/kroxn/visual/refs/heads/main/weapon.lua")
			if downloaded then lua=downloaded;flag16=false else lua=cachedLua;flag16=lua~=nil end
		end

		if not lua then
			error("[MM2Viz] could not fetch mesh data from " .. "https://raw.githubusercontent.com/kroxn/visual/refs/heads/main/weapon.lua" .. " -- " .. tostring(v11), 0)
		end

		local chunk, v12 = loadstring(lua .. "\nreturn MESHES_FULL")

		if not chunk and flag16 then
			lua = fn59("https://raw.githubusercontent.com/kroxn/visual/refs/heads/main/weapon.lua")
			chunk = lua and loadstring(lua .. "\nreturn MESHES_FULL")
			flag16 = false
			v12 = nil
		end

		if not chunk then
			error("[MM2Viz] mesh data failed to compile -- " .. tostring(v12), 0)
		end

		if not flag16 and writefile then
			pcall(function()
				if makefolder and isfolder and not isfolder("LessV2") then
					makefolder("LessV2")
				end

				writefile("LessV2/weapon.lua", lua)
			end)
		end

		local v13 = chunk()

		if type(v13) ~= "table" or next(v13) == nil then
			error("[MM2Viz] fetched file produced no MESHES_FULL table (is the URL the data file?)", 0)
		end

		local tbl13 = {}

		for k, v14 in pairs(v13) do
			tbl13[k] = v14
		end

		local sweetChroma = tbl13.SweetChroma

		if sweetChroma and sweetChroma.Model and not tbl13.Sweet then
			local fn60 = nil

			fn60 = function(arg)
				local tbl14 = { Class = arg.Class, Id = arg.Id, Name = arg.Name, Props = arg.Props, Tags = arg.Tags }

				if arg.Children then
					tbl14.Children = {}

					for _, child in ipairs(arg.Children) do
						if not (child.Class == "Decal" and child.Name == "Chroma") then
							tbl14.Children[#tbl14.Children + 1] = fn60(child)
						end
					end
				end

				return tbl14
			end

			local tbl14 = {}
			local v14 = pairs
			local meta = sweetChroma.Meta or {}

			for k, v15 in v14(meta) do
				tbl14[k] = v15
			end

			tbl14.Chroma = nil
			tbl13.Sweet = { Complete = false, Meta = tbl14, Model = fn60(sweetChroma.Model) }
		end

		local tbl14 = { Godly = true, Ancient = true }

		local function fn60(arg)
			local str = tostring(arg or "")
			return str == "" or str:match("^%?+$") ~= nil
		end

		local tbl15 = {}
		local n4 = 0

		for k, v14 in pairs(tbl13) do
			local v15 = weapons[k]
			local meta = type(v14) == "table" and v14.Meta or nil
			local itemType = type(v15) == "table" and v15.ItemType or meta and meta.ItemType
			local rarity = type(v15) == "table" and v15.Rarity or meta and meta.Rarity
			local itemName = type(v15) == "table" and v15.ItemName or meta and meta.ItemName or k

			if type(v14) == "table" and (v14.Model or v14.Display) and (itemType == "Knife" or itemType == "Gun") and tbl14[rarity] and not fn60(itemName) then
				tbl15[k] = v14
			else
				n4 += 1
			end
		end

		local v14 = tbl15
		local n5 = 0
		local n6 = 0

		for _, v15 in pairs(v14) do
			n5 += 1

			if v15.Model then
				n6 += 1
			end
		end

		local RunService_ = game:GetService("RunService")
		local CollectionService_ = game:GetService("CollectionService")

		local function fn61(arg)
			if type(arg) == "string" then
				return (arg:gsub("^%s+", ""):gsub("%s+$", ""))
			end
			return arg
		end

		local function fnImage(arg)
			if type(arg) == "number" then
				return "rbxassetid://" .. tostring(math.floor(arg))
			end
			if type(arg) ~= "string" then return nil end
			local value = arg:gsub("^%s+", ""):gsub("%s+$", "")
			if value == "" then return nil end
			if value:match("^%d+$") then
				return "rbxassetid://" .. value
			end
			return value
		end

		local function fn62(arg, arg2, arg3)
			for k, v15 in pairs(arg2) do
				if not (arg3 and arg3[k]) then
					if k == "MeshId" or k == "TextureId" or k == "TextureID" or k == "Texture" then
						v15 = fn61(v15)
					end

					pcall(function()
						arg[k] = v15
					end)
				end
			end
		end

		local function createPart(arg)
			local v15 = fn61(arg.MeshId or "")
			local size = arg.Size or Vector3.one
			local v16 = nil

			pcall(function()
				v16 = game:GetService("InsertService"):CreateMeshPartAsync(v15, Enum.CollisionFidelity.Box, Enum.RenderFidelity.Precise)
			end)

			if v16 then
				pcall(function()
					v16.Size = size
				end)

				return v16
			end

			local part = New("Part")
			part.Size = size
			local specialMesh = New("SpecialMesh")
			specialMesh.MeshType = Enum.MeshType.FileMesh

			pcall(function()
				specialMesh.MeshId = v15
			end)

			pcall(function()
				specialMesh.TextureId = fn61(arg.TextureID or "")
			end)

			specialMesh.Parent = part
			return part
		end

		local tbl16 = {}
		local color2 = Color3.fromRGB(255, 0, 0)
		local color3 = Color3.fromRGB(255, 255, 0)
		local color4 = Color3.fromRGB(0, 255, 0)
		local color5 = Color3.fromRGB(0, 255, 255)
		local color6 = Color3.fromRGB(0, 0, 255)
		local color7 = Color3.fromRGB
		tbl16[1] = color2
		tbl16[2] = color3
		tbl16[3] = color4
		tbl16[4] = color5
		tbl16[5] = color6

		do
			local values = table.pack(color7(255, 0, 255))
			table.move(values, 1, values.n, 6, tbl16)
		end

		local function fn63(arg)
			local n7 = #tbl16
			local n8 = arg % n7
			local n9 = math.floor(n8)
			return tbl16[n9 + 1]:Lerp(tbl16[(n9 + 1) % n7 + 1], n8 - n9)
		end

		local function fn64(arg, arg2)
			if arg2.Meta and arg2.Meta.Chroma == true then
				return true
			end
			return arg:sub(-6) == "Chroma"
		end

		local n7 = 1.8
		local texture = "rbxassetid://18363392181"

		local function fn65(arg, forceColorCycle)
			local tbl17 = {}
			local tbl18 = {}
			local tbl19 = {}
			local tbl20 = {}
			local flag17 = false

			for _, descendant in ipairs(arg:GetDescendants()) do
				local attribute = descendant:GetAttribute("MM2Chroma")

				if attribute then
					if attribute == "part" then
						tbl17[#tbl17 + 1] = descendant
						flag17 = true
					elseif attribute == "decal" and descendant:IsA("Decal") then
						pcall(function()
							descendant.Texture = texture
						end)

						tbl18[#tbl18 + 1] = descendant
						flag17 = true
					else
						flag17 = true

						if attribute == "fire" then
							tbl19[#tbl19 + 1] = descendant
						end
					end
				end
			end

			if not flag17 then
				for _, descendant in ipairs(arg:GetDescendants()) do
					if descendant:IsA("Decal") and descendant.Name:lower():find("chroma") then
						tbl18[#tbl18 + 1] = descendant
					elseif descendant:IsA("Fire") then
						tbl19[#tbl19 + 1] = descendant
					end
				end
			end

			if forceColorCycle then
				for _, descendant in ipairs(arg:GetDescendants()) do
					if descendant:IsA("BasePart") then
						tbl17[#tbl17 + 1] = descendant
					elseif descendant:IsA("SpecialMesh") and descendant.TextureId ~= "" then
						tbl20[#tbl20 + 1] = descendant
					end
				end
			end

			local tbl21 = {}

			for _, v15 in ipairs(tbl19) do
				if v15:IsA("BasePart") then
					tbl21[v15] = true
				end
			end

			for _, v15 in ipairs(tbl17) do
				tbl21[v15] = nil
			end

			for _, descendant in ipairs(arg:GetDescendants()) do
				if descendant:IsA("SpecialMesh") and descendant.TextureId ~= "" and tbl21[descendant.Parent] then
					tbl20[#tbl20 + 1] = descendant
				end
			end

			if arg:IsA("Part") and tbl21[arg] then
				local specialMesh = arg:FindFirstChildWhichIsA("SpecialMesh")

				if specialMesh and specialMesh.TextureId ~= "" then
					tbl20[#tbl20 + 1] = specialMesh
				end
			end

			if #tbl17 == 0 and #tbl18 == 0 and #tbl19 == 0 and #tbl20 == 0 then
				return nil
			end

			return Connect(RunService_.Heartbeat, function()
				local now = os.clock()
				local v15 = fn63(now)

				for _, v16 in ipairs(tbl18) do
					v16.Color3 = v15
				end

				for _, v16 in ipairs(tbl20) do
					v16.VertexColor = Vector3.new(v15.R, v15.G, v15.B)
				end

				for _, v16 in ipairs(tbl19) do
					if v16:IsA("Fire") then
						v16.Color = v15
					elseif v16:IsA("BasePart") then
						v16.Color = v15
					end
				end

				local n8 = math.floor(now * n7)

				for i, v16 in ipairs(tbl17) do
					v16.Color = tbl16[(n8 + i - 1) % #tbl16 + 1]
				end
			end)
		end

		local tbl17 = {
			WeldConstraint = true,
			Weld = true,
			Motor6D = true,
			RigidConstraint = true,
			Bone = true,
			Snap = true,
			ManualWeld = true,
			Rotate = true,
			RotateP = true,
			RotateV = true,
		}

		local function fn66(arg, arg2)
			if not (arg and arg2.Tags) then
				return
			end

			for _, tag in ipairs(arg2.Tags) do
				local str = tag == "ChromaPart" and "part" or tag == "ChromaDecal" and "decal"
				local str2

				if str then
					str2 = str
				else
					str2 = tag == "ChromaFire" and "fire"
				end

				str2 = str2 or nil

				if str2 then
					pcall(function()
						arg:SetAttribute("MM2Chroma", str2)
					end)
				end
			end
		end

		local function fn67(arg)
			local class = arg.Class
			if tbl17[class] then
				return nil
			end
			local v15

			if class == "MeshPart" then
				v15 = createPart(arg.Props)
				fn62(v15, arg.Props, { MeshId = true, Size = true, RelCF = true, CanCollide = true })
			else
				local ok, result = pcall(New, class)
				if not ok or not result then
					return nil
				end
				v15 = result
				fn62(v15, arg.Props, { RelCF = true })
			end

			if arg.Name then
				pcall(function()
					v15.Name = arg.Name
				end)
			end

			fn66(v15, arg)
			return v15
		end

		local fn68 = nil

		fn68 = function(arg, parent, parent2, arg2, arg3, arg4)
			local v15 = ipairs
			local children = arg.Children or {}

			for _, child in v15(children) do
				local v16 = fn67(child)

				if v16 then
					arg2[child.Id] = v16

					if v16:IsA("BasePart") then
						v16.Anchored = false
						v16.CanCollide = false
						v16.CanQuery = false
						v16.CanTouch = false
						v16.Massless = true
						arg3[#arg3 + 1] = { inst = v16, relcf = child.Props.RelCF }
						v16.Parent = parent2
						fn68(child, v16, parent2, arg2, arg3, arg4)
					elseif v16:IsA("Attachment") then
						if child.Props.RelCF then
							pcall(function()
								v16.CFrame = child.Props.RelCF
							end)
						end

						v16.Parent = parent2
						fn68(child, v16, parent2, arg2, arg3, arg4)
					elseif v16:IsA("Beam") or v16:IsA("Trail") then
						v16.Parent = parent
						arg4[#arg4 + 1] = { inst = v16, a0 = child.Att0, a1 = child.Att1 }
						fn68(child, v16, parent2, arg2, arg3, arg4)
					else
						v16.Parent = parent
						fn68(child, v16, parent2, arg2, arg3, arg4)
					end
				else
					fn68(child, parent, parent2, arg2, arg3, arg4)
				end
			end
		end

		local function fn69(arg)
			local model = arg.Model
			if not model then
				return nil
			end
			local part

			if model.Class == "MeshPart" then
				part = createPart(model.Props)
				fn62(part, model.Props, { MeshId = true, Size = true, RelCF = true, CanCollide = true })
			else
				part = New("Part")
				fn62(part, model.Props, { RelCF = true, CanCollide = true })
			end

			if model.Name then
				pcall(function()
					part.Name = model.Name
				end)
			end

			fn66(part, model)
			part.Anchored = false
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.Massless = true
			local tbl18 = { [model.Id] = part }
			local tbl19 = {}
			local tbl20 = {}
			fn68(model, part, part, tbl18, tbl19, tbl20)

			for _, v15 in ipairs(tbl20) do
				if v15.a0 and tbl18[v15.a0] then
					pcall(function()
						v15.inst.Attachment0 = tbl18[v15.a0]
					end)
				end

				if v15.a1 and tbl18[v15.a1] then
					pcall(function()
						v15.inst.Attachment1 = tbl18[v15.a1]
					end)
				end
			end

			return { root = part, parts = tbl19 }
		end

		local function fn70(arg, cFrame)
			local root = arg.root

			pcall(function()
				root.CFrame = cFrame
			end)

			for _, part in ipairs(arg.parts) do
				if part.relcf then
					pcall(function()
						part.inst.CFrame = cFrame * part.relcf
					end)
				end

				local weldConstraint = New("WeldConstraint")
				weldConstraint.Part0 = part.inst
				weldConstraint.Part1 = root
				weldConstraint.Parent = part.inst
			end

			return root
