		end

		if tbl.whBreak then
			return false
		end
		local v7 = tbl.whUrlNow()

		for _, whHost in ipairs(tbl.WH_HOSTS) do
			if v7:find("^https://" .. whHost:gsub("%.", "%%.") .. "/api/webhooks/") then
				return true
			end
		end

		return false
	end

