	tbl.whReward = function(arg, arg2, arg3)
		if not tbl.whReady() then
			return false, "no webhook set"
		end
		local str = tostring(arg or ""):gsub("^%s*[xX]%s*", "")
		local v7 = tonumber
		local str2 = str:gsub("[^%d%.]", "")
		local str3 = v7(str2)

