-- Less Nova 1.1: native HUD, original Less cursor/skins and complete farm UI.
do
    settings.hud=settings.hud or {round=false}
    Buttons:Sub("UIS");Buttons:Header("HUD")
    local section=Buttons:LastSection()
    local rawWatermark=Window.SetWatermark
    local syncing=false
    local pingControl
    function Window:SetWatermark(value)
        rawWatermark(self,value)
        if syncing then return end
        syncing=true
        if pingControl then pingControl:SetSilent(value==true) end
        if self.AppearanceRefs and self.AppearanceRefs.watermark then self.AppearanceRefs.watermark:SetSilent(value==true)end
        syncing=false
    end
    pingControl=section:Toggle({Text="Show Ping/Fps UI",Default=Window.State.get("watermark",false)==true,
        Callback=function(value)Window:SetWatermark(value)end})
    local gui=Make("ScreenGui",{Name="LessNovaRoundHUD",ResetOnSpawn=false,IgnoreGuiInset=false,DisplayOrder=100},Host)
    local label=Make("TextLabel",{Name="RoundTime",AnchorPoint=Vector2.new(0.5,0),Position=UDim2.new(0.5,0,0,12),
        Size=UDim2.fromOffset(170,32),BackgroundColor3=Color3.fromHex("26172F"),BackgroundTransparency=0.12,
        TextColor3=Color3.fromHex("FFC06B"),TextSize=16,Font=Enum.Font.GothamBold,Text="Lobby",Visible=false},gui)
    Round(label,10);Stroke(label,Color3.fromHex("FF8A24"),1,0.25)
    local function updateRound()
        label.Visible=settings.hud.round==true
        if not label.Visible then return end
        local timer=World:FindFirstChild("RoundTimerPart")
        local seconds=timer and tonumber(timer:GetAttribute("Time"))
        label.Text=seconds and seconds>0 and string.format("Round  %d:%02d",math.floor(seconds/60),math.floor(seconds%60)) or "Lobby"
    end
    Buttons:Toggle({Text="Show Round Timer",Default=settings.hud.round,Callback=function(value)settings.hud.round=value;updateRound()end})
    local elapsed=0
    Connect(RunService.Heartbeat,function(dt)elapsed+=dt;if elapsed>=0.25 then elapsed=0;updateRound()end end)
    config.applyHooks[#config.applyHooks+1]=updateRound
    Private.LessHUD={Update=updateRound,Label=label,Ping=pingControl}
end

