    local mouse=LocalPlayer:GetMouse();local originalMouseIcon=mouse.Icon
    local gui=Make("ScreenGui",{Name="LessNovaCrosshair",ResetOnSpawn=false,IgnoreGuiInset=true,DisplayOrder=10000},Host)
    local cursor=Make("ImageLabel",{Name="Cursor",AnchorPoint=Vector2.new(0.5,0.5),BackgroundTransparency=1,
        Size=UDim2.fromOffset(cfg.size,cfg.size),Visible=false},gui)
    local function applyCursor()
        local active=cfg.style~="Default" and Private.LessCursors[cfg.style]~=nil
        local char=LocalPlayer.Character
        local hasGun=char and char:FindFirstChild("Gun")~=nil
        cursor.Visible=active and (not cfg.onlyWithGun or hasGun)
        cursor.Image=Private.LessCursors[cfg.style] or ""
        cursor.Size=UDim2.fromOffset(cfg.size,cfg.size)
        if cursor.Visible then Input.MouseIconEnabled=false else Input.MouseIconEnabled=originalIcon end
    end
    local choices={};for name in pairs(Private.LessCursors)do choices[#choices+1]={code=name,label=name}end
    table.sort(choices,function(a,b)if a.code=="Default" then return true elseif b.code=="Default" then return false end;return a.code<b.code end)
    local cursorPicker=visuals:Dropdown({Text="Cursor style",Default=cfg.style,Options=choices,Callback=function(value)cfg.style=value;applyCursor()end})
    visuals:Slider({Text="Crosshair Size",Min=12,Max=80,Decimals=0,Default=cfg.size,Callback=function(value)cfg.size=value;applyCursor()end})
    visuals:Toggle({Text="Spin Cursor",Default=cfg.spin,Callback=function(value)cfg.spin=value end})
    visuals:Toggle({Text="Only with gun equipped",Default=cfg.onlyWithGun,Callback=function(value)cfg.onlyWithGun=value;applyCursor()end})
    visuals:Note({Text="Click a preview to apply the cursor, or choose one from Cursor style."})
    local cursorGrid=visuals:Grid({Columns=4,Height=82,Gap=6})
    for index,item in ipairs(choices)do
        local name=item.code
        local card=cursorGrid:Card({Name=name})
        local button=Make("TextButton",{Name="Preview",Text="",AutoButtonColor=true,BackgroundTransparency=1,Size=UDim2.fromScale(1,1),LayoutOrder=index},card.card)
        Make("ImageLabel",{BackgroundTransparency=1,Image=Private.LessCursors[name]or"",Position=UDim2.new(0.5,-22,0,4),Size=UDim2.fromOffset(44,44),ScaleType=Enum.ScaleType.Fit},button)
        Make("TextLabel",{BackgroundTransparency=1,Text=name,TextWrapped=true,Font=Enum.Font.Gotham,TextSize=10,TextColor3=Color3.fromHex("FFF1DE"),Position=UDim2.new(0,2,1,-29),Size=UDim2.new(1,-4,0,25)},button)
        Connect(button.Activated,function()cursorPicker.Set(name)end)
    end
    Connect(RunService.RenderStepped,function(dt)
        applyCursor()
        if cursor.Visible then
            local pos=Input:GetMouseLocation();cursor.Position=UDim2.fromOffset(pos.X,pos.Y)
            cursor.Rotation=cfg.spin and (cursor.Rotation+dt*55)%360 or 0
        end
    end)
    OnCleanup(function()Input.MouseIconEnabled=originalIcon;mouse.Icon=originalMouseIcon end)
    config.applyHooks[#config.applyHooks+1]=applyCursor
    Private.LessCursor={Apply=applyCursor,Image=cursor}
end

do
    local tab=UI:Tab("Visuals","eye");tab:Sub("WSkins");tab:Header("Visual Skin Changer — Less")
    local status=tab:Note({Text="Loading skins…"})
    local engine,busy,query=nil,false,""
    local grid=tab:Grid({Columns=4,Height=84,Gap=6})
    local tiles={}
    local function filter()
        local shown=0
        for _,entry in ipairs(tiles)do
            local visible=query=="" or entry.search:find(query,1,true)~=nil
            entry.card.Visible=visible
            if visible then shown+=1 end
        end
        if engine then status.Text=string.format("%d skins — click one to add it, then equip it normally.",shown)end
    end
    local function buildCatalog()
        local ordered={}
        for _,item in ipairs(engine.list)do ordered[#ordered+1]=item end
        local rarityOrder={Ancient=1,Godly=2}
        table.sort(ordered,function(a,b)
            local left,right=rarityOrder[a.rarity]or 3,rarityOrder[b.rarity]or 3
            if left~=right then return left<right end
            return tostring(a.name):lower()<tostring(b.name):lower()
        end)
        for index,item in ipairs(ordered)do
            local card=grid:Card({Name="",Value=""})
            local button=Make("TextButton",{Name=item.key,Text="",AutoButtonColor=false,BackgroundColor3=Color3.fromRGB(10,10,13),BackgroundTransparency=0.25,BorderSizePixel=0,Size=UDim2.fromScale(1,1),LayoutOrder=index},card.card)
            Round(button,10);Stroke(button,Color3.fromRGB(255,255,255),1.5,0.55)
            local image=engine.catalogImage and engine.catalogImage(item.key)or engine.icon(item.key)or""
            Make("ImageLabel",{BackgroundTransparency=1,AnchorPoint=Vector2.new(0.5,0),Position=UDim2.new(0.5,0,0,5),Size=UDim2.fromOffset(56,56),Image=image,ScaleType=Enum.ScaleType.Fit},button)
            Make("TextLabel",{BackgroundTransparency=1,AnchorPoint=Vector2.new(0.5,1),Position=UDim2.new(0.5,0,1,-4),Size=UDim2.new(1,-6,0,18),Font=Enum.Font.GothamBold,TextSize=10,TextWrapped=true,TextColor3=Color3.fromRGB(200,200,210),Text=item.name},button)
            if item.chroma then
                local badge=Make("TextLabel",{Name="ChromaTag",BackgroundColor3=Color3.fromRGB(48,26,62),BackgroundTransparency=0.15,AnchorPoint=Vector2.new(0,1),Position=UDim2.new(0,3,0,61),Size=UDim2.fromOffset(36,11),Font=Enum.Font.GothamBold,TextSize=8,TextColor3=Color3.fromRGB(255,255,255),Text="Chroma",ZIndex=5},button)
                Round(badge,4)
            end
            Connect(button.Activated,function()
                local ok=pcall(engine.spawn,item.key,1)
                status.Text=ok and(item.name.." — equip it from your inventory.")or("Couldn't add "..item.name.." to your inventory.")
            end)
            tiles[#tiles+1]={card=card.card,search=tostring(item.name):lower()}
            if index%60==0 then task.wait()end
        end
        filter()
        task.spawn(function()
            local preload={}
            for _,entry in ipairs(tiles)do
                local image=entry.card:FindFirstChildWhichIsA("ImageLabel",true)
                if image then preload[#preload+1]=image end
            end
            pcall(function()game:GetService("ContentProvider"):PreloadAsync(preload)end)
        end)
    end
    local searchInput=tab:Input({Text="Search skins",Default="",Placeholder="Type a skin name…",Callback=function(value)query=tostring(value):lower();filter()end})
    -- The regular input adopts a muted surface on some Nova themes. Keep the
    -- typed text and placeholder legible independently of the active theme.
    if searchInput.Box then
        local box=searchInput.Box
        box.TextColor3=Color3.fromHex("FFF1DE")
        box.PlaceholderColor3=Color3.fromHex("CEB4D9")
        box.TextTransparency=0
        local field=box.Parent
        if field then
            field.BackgroundColor3=Color3.fromHex("24132E")
            field.BackgroundTransparency=0.08
        end
    end
    task.spawn(function()
        local identity=getthreadidentity and getthreadidentity()
        local ok,result=pcall(Private.CreateLessSkins,false)
        if identity and setthreadidentity then pcall(setthreadidentity,identity)end
        busy=false
        if not ok or not result then
            status.Text="Couldn't load skins: "..tostring(result):sub(1,120)
            recordError("less_skins",result)
            return
        end
        if not Alive()then result.destroy();return end
        engine=result
        if engine.gui then engine.gui.Enabled=false end
        buildCatalog()
    end)
    OnCleanup(function()local current=engine or Private.__MM2Viz;if current and current.destroy then current.destroy()end end)
end

do
    local tab=UI:Tab("Servers","server")
    local teleport=Services.TeleportService
    local status=tab:Note({Text="Ready to look for public servers."})
    local requestedJobId=""
    settings.autoReconnect=settings.autoReconnect or {enabled=false}
    if type(settings.autoReconnect)~="table" then settings.autoReconnect={enabled=false} end
    local reconnectCfg=settings.autoReconnect
    reconnectCfg.scriptUrl=tostring(reconnectCfg.scriptUrl or "")
    if reconnectCfg.scriptUrl=="" then reconnectCfg.scriptUrl="https://raw.githubusercontent.com/SixK1ng/gg/main/lessv2.lua" end
    local reconnectBusy=false
    local reconnectPromptConnection
    local function queueReconnectScript()
        local url=tostring(reconnectCfg.scriptUrl or ""):gsub("%s+","")
        if not url:match("^https://") or url:find("tu%-url",1) then
            return false,"Set a public HTTPS script URL to enable reloading after teleport."
        end
        local queueFn=queue_on_teleport or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport)
        if type(queueFn)~="function" then return false,"This executor does not expose queue_on_teleport." end
        local queuedCode="repeat task.wait() until game:IsLoaded()\nloadstring(game:HttpGet("..string.format("%q",url).."))()"
        local ok,err=pcall(queueFn,queuedCode)
        return ok,err
    end
    local function isConnectionPrompt(prompt)
        local parts={}
        for _,object in ipairs(prompt:GetDescendants())do
            if object:IsA("TextLabel") or object:IsA("TextButton") then
                parts[#parts+1]=tostring(object.Text or "")
            end
        end
        local message=table.concat(parts," "):lower()
        return message:find("lost connection",1,true)~=nil
            or message:find("connection lost",1,true)~=nil
            or message:find("connection attempt failed",1,true)~=nil
            or message:find("failed to connect",1,true)~=nil
            or message:find("internet connection",1,true)~=nil
            or message:find("disconnected",1,true)~=nil
            or message:find("error code: 277",1,true)~=nil
            or message:find("error code: 279",1,true)~=nil
            or message:find("error code: 266",1,true)~=nil
    end
    local function reconnectAfterConnectionLoss()
        if not reconnectCfg.enabled or reconnectBusy then return end
        reconnectBusy=true
        local queued,queueError=queueReconnectScript()
        if not queued then Notify("Reconnect script will not reload: "..tostring(queueError),"Auto Reconnect","warning") end
        local placeId,jobId=game.PlaceId,game.JobId
        local teleportStarted=false
        local teleportConnection
        pcall(function()
            teleportConnection=LocalPlayer.OnTeleport:Connect(function(state)
                if state==Enum.TeleportState.Started or state==Enum.TeleportState.InProgress
                    or state==Enum.TeleportState.WaitingForServer then teleportStarted=true end
            end)
        end)
        task.spawn(function()
            for attempt=1,3 do
                if not reconnectCfg.enabled or teleportStarted then break end
                local ok,err=pcall(function()
                    if attempt==1 and jobId~="" then
                        teleport:TeleportToPlaceInstance(placeId,jobId,LocalPlayer)
                    else
                        teleport:Teleport(placeId,LocalPlayer)
                    end
                end)
                if not ok then Notify("Reconnect attempt "..attempt.." failed: "..tostring(err),"Auto Reconnect","warning") end
                local deadline=os.clock()+8
                while os.clock()<deadline and reconnectCfg.enabled and not teleportStarted do task.wait(0.25) end
                if attempt<3 and reconnectCfg.enabled and not teleportStarted then task.wait(attempt*2) end
            end
            if teleportConnection then pcall(function()teleportConnection:Disconnect()end) end
            reconnectBusy=false
        end)
    end
    tab:Toggle({Text="Auto Reconnect",Default=reconnectCfg.enabled==true,Callback=function(value)
        reconnectCfg.enabled=value==true
        settings.autoReconnect=reconnectCfg
    end})
    tab:Note({Text="On connection errors, tries this server first, then Roblox matchmaking. A public HTTPS script URL is required to reload the script after teleport. Three attempts maximum."})
    task.spawn(function()
        local coreGui=game:GetService("CoreGui")
        local promptGui=coreGui:WaitForChild("RobloxPromptGui",30)
        local overlay=promptGui and promptGui:WaitForChild("promptOverlay",30)
        if not overlay then return end
        local function watchPrompt(child)
            if child.Name~="ErrorPrompt" then return end
            task.spawn(function()
                for _=1,6 do
                    if not child.Parent then return end
                    if isConnectionPrompt(child) then reconnectAfterConnectionLoss();return end
                    task.wait(0.2)
                end
            end)
        end
        reconnectPromptConnection=overlay.ChildAdded:Connect(watchPrompt)
        for _,child in ipairs(overlay:GetChildren())do watchPrompt(child)end
    end)
    OnCleanup(function()
        if reconnectPromptConnection then pcall(function()reconnectPromptConnection:Disconnect()end)end
        reconnectCfg.enabled=false
    end)
    tab:Header("Public Server Browser")
    tab:Note({Text="Searches the current MM2 place only. Teleporting happens only after you press one of the join buttons."})

    local function getServers(order, pages)
        local all,cursor={},nil
        for _=1,pages do
            local url="https://games.roblox.com/v1/games/"..tostring(game.PlaceId).."/servers/Public?sortOrder="..order.."&excludeFullGames=true&limit=100"
            if cursor and cursor~="" then url=url.."&cursor="..Http:UrlEncode(cursor) end
            local ok,body=pcall(function()return game:HttpGet(url)end)
            if not ok then return nil,"The public-server list could not be loaded." end
            local decodedOk,payload=pcall(function()return Http:JSONDecode(body)end)
            if not decodedOk or type(payload)~="table" then return nil,"The server list returned an invalid response." end
            for _,server in ipairs(payload.data or {})do
                if type(server)=="table" and server.id and server.id~=game.JobId
                    and tonumber(server.playing or 0)<tonumber(server.maxPlayers or 0) then
                    all[#all+1]=server
                end
            end
            cursor=payload.nextPageCursor
            if not cursor or cursor=="" then break end
            task.wait(0.15)
        end
        return all
    end
    local function join(server, label)
        if not server or not server.id then Notify("No available server was found.","Servers","warning");return end
        status.Text="Joining "..(label or "server").."…"
        local ok,err=pcall(function()teleport:TeleportToPlaceInstance(game.PlaceId,server.id,LocalPlayer)end)
        if not ok then
            status.Text="Couldn't start the teleport."
            Notify(tostring(err),"Servers","warning")
        end
    end
    tab:Button({Text="Server Hop",Callback=function()
        status.Text="Looking for a public server…"
        task.spawn(function()
            local servers,err=getServers("Desc",3)
            if not servers then status.Text=err;Notify(err,"Servers","warning");return end
            if #servers==0 then status.Text="No joinable public server was found.";return end
            join(servers[math.random(1,#servers)],"a public server")
        end)
    end})
    tab:Button({Text="Join Smallest Server",Callback=function()
        status.Text="Looking for the smallest public server…"
        task.spawn(function()
            local servers,err=getServers("Asc",2)
            if not servers then status.Text=err;Notify(err,"Servers","warning");return end
            table.sort(servers,function(a,b)return tonumber(a.playing or math.huge)<tonumber(b.playing or math.huge)end)
            if #servers==0 then status.Text="No joinable public server was found.";return end
            join(servers[1],"the smallest available server")
        end)
    end})
    tab:Button({Text="Rejoin Current Server",Callback=function()
        status.Text="Rejoining the current server…"
        local ok,err=pcall(function()teleport:TeleportToPlaceInstance(game.PlaceId,game.JobId,LocalPlayer)end)
        if not ok then status.Text="Couldn't start the rejoin.";Notify(tostring(err),"Servers","warning")end
    end})
    tab:Button({Text="Copy Current Server ID",Callback=function()
        local copy=setclipboard or toclipboard or (syn and syn.set_clipboard)
        if type(copy)~="function" then Notify("Clipboard support is unavailable in this executor.","Servers","warning");return end
        local ok=pcall(copy,game.JobId)
        if ok then status.Text="Current server ID copied." else Notify("Couldn't copy the server ID.","Servers","warning")end
    end})
    tab:Header("Join a Specific Server")
    tab:Input({Text="Server ID",Default="",Placeholder="Paste a Job ID",Callback=function(value)requestedJobId=tostring(value):gsub("%s+","")end})
    tab:Button({Text="Join Entered Server",Callback=function()
        if requestedJobId=="" then Notify("Enter a server ID first.","Servers","warning");return end
        join({id=requestedJobId},"the entered server")
    end})
end

do
    local farm=Private.LessFarm
    local tab=UI:Tab("Autofarm","coins")
    settings.farm=settings.farm or {speed=25,reset=true,hop=false,claim=false,fling=false,kill=false,boxes={}}
    local cfg=settings.farm;cfg.boxes=cfg.boxes or {}
    local enabled=false
    tab:Header("Coin Autofarm — Less")
    -- Automatic movement, purchases and webhook sending always require activating their controls.
    local toggle=tab:Toggle({Text="Coin Autofarm",NoSave=true,Default=false,Callback=function(value)
        enabled=value
        if value then
            settings.fly.on=false
            for key,setter in pairs(setters)do
                if key:match("^Movement/") and key:match("/Fly$")then setter(false)end
            end
            farm.start()
        else farm.stop()end
    end})
    tab:Slider({Text="Farm Speed",Min=5,Max=25,Decimals=0,Default=cfg.speed,Callback=function(value)cfg.speed=value;farm.setSpeed(value)end})
    tab:Header("Settings")
    local perfKeys={"gfxLow","noShadows","noLights","noPost","noFx","noTex","plastic","simplePlayers","stopAnims"}
    local savedPerformance
    local function performance(value)
        local optimizer=Private.__lessOptimizer
        if not optimizer then Notify("The optimizer has not initialized.");return end
        if value then
            if savedPerformance then return end
            savedPerformance={}
            for _,key in ipairs(perfKeys)do
                savedPerformance[key]=settings.optim[key]==true
                if optimizer.controls[key]then optimizer.controls[key].Set(true)end
            end
        elseif savedPerformance then
            for _,key in ipairs(perfKeys)do if optimizer.controls[key]then optimizer.controls[key].Set(savedPerformance[key])end end
            savedPerformance=nil
        else
            return
        end
        optimizer.refresh()
    end
    tab:Toggle({Text="Performance Mode",NoSave=true,Default=false,Callback=performance})
    tab:Toggle({Text="Hop When Server Dies",Default=cfg.hop,Callback=function(value)cfg.hop=value;farm.farmHopOn=value end})
    farm.populatedHop=function()
        if not enabled or not cfg.hop then return false end
        Notify("The server is empty. Looking for another match.","Autofarm")
        Services.TeleportService:Teleport(game.PlaceId,LocalPlayer)
        return false -- If teleport did not leave this client, retry after the cooldown.
    end
    tab:Toggle({Text="Anti-AFK",Default=settings.afk.on,Callback=function(value)
        settings.afk.on=value
        flag13=value==true
        if flag13 then fn31() else fn32() end
    end})
    if settings.afk.on then flag13=true;fn31() end
    tab:Toggle({Text="Auto-Reset When Bag Full",Default=cfg.reset,Callback=function(value)cfg.reset=value;farm.setReset(value and enabled)end})
    local baseStart,baseStop=farm.start,farm.stop
    farm.start=function()baseStart();farm.setReset(cfg.reset)end
    farm.stop=function()farm.setReset(false);baseStop()end
    tab:Toggle({Text="Auto Claim Shells / Rewards",NoSave=true,Default=false,Callback=function(value)
        cfg.claim=value;farm.shellsOn=value;if value then farm.startShells()else farm.stopShells()end
    end})
    tab:Toggle({Text="Fling Murderer When Done",Default=cfg.fling,Callback=function(value)cfg.fling=value;farm.flingWhenDone=value;farm.flingDoneFired=false end})
    tab:Toggle({Text="Kill All When Bag Full",Default=cfg.kill,Callback=function(value)cfg.kill=value;farm.killWhenFull=value;farm.killFired=false end})
    tab:Header("Auto Open Boxes")
    tab:Note({Text="Each enabled box spends the required in-game currency when you have enough. Only available boxes can open."})
    farm.el.box={}
    for _,item in ipairs(farm.BOXES)do
        local key,name=item[1],item[2]
        farm.el.box[key]=tab:Toggle({Text="Auto Open "..name,NoSave=true,Default=false,Callback=function(value)
            cfg.boxes[key]=value;farm.boxOn[key]=value
            if value then farm.startBox(key,name)else farm.stopBox(key)end
        end})
    end
    tab:Header("Discord Webhook")
    tab:Note({Text="Optional: your webhook receives round, reward and box logs only while Start Sender is on."})
    -- Webhook credentials stay in memory; never export them in shared configurations.
    local webhook=tab:LastSection():Input({Text="Webhook URL",Default="",Placeholder="https://discord.com/api/webhooks/…",
        Callback=function(value)farm.WH_URL=tostring(value);farm.whBreak=false;farm.saidHello=false;farm.whLastErr=nil end})
    local sender
    sender=tab:Toggle({Text="Start Sender",NoSave=true,Default=false,Callback=function(value)
        farm.whOn=value
        if value then task.spawn(function()
            local ok,err=farm.whHello()
            if not ok then farm.whOn=false;if sender then sender.Set(false)end end
            Notify(ok and "Round logging is enabled." or tostring(err),"Webhook")
        end)end
    end})
    -- Supply the old Less settings report through its original flag format.
    farm.config={Elements={}}
    local function updateFlags()
        local values={Toggle_Coin_Autofarm=enabled,Slider_Farm_Speed=cfg.speed,Toggle_Farm_Perf_Master=savedPerformance~=nil,
            Toggle_Farm_Dead_Hop=cfg.hop,Toggle_Anti_AFK=settings.afk.on,Toggle_Auto_Reset_When_Bag_Full=cfg.reset,
            Toggle_Auto_Claim_Shells=cfg.claim,Toggle_Fling_Murderer_When_Done=cfg.fling,Toggle_Kill_All_When_Bag_Full=cfg.kill}
        for key,value in pairs(values)do farm.config.Elements[key]={__type=type(value)=="number"and"Slider"or"Toggle",Value=value}end
    end
    updateFlags();local elapsed=0
    Connect(RunService.Heartbeat,function(dt)elapsed+=dt;if elapsed>=1 then elapsed=0;updateFlags()end end)
    OnCleanup(function()performance(false)end)
    Private.LessFarmUI={Toggle=toggle,Performance=performance,Config=cfg,IsRunning=function()return enabled end}
end

do
    local farm=Private.LessFarm
    local tab=UI:Tab("Autofarm","coins")
    settings.roleFarm=settings.roleFarm or {innocent=false,sheriff=false,murderer=false,exp=false}
    local cfg=settings.roleFarm
    local running=false
    local applied={killAll=false}
    local lastShot=0
    local statusLabel
    local function currentRole()
        local rec=farm and farm.myRoundRec and farm.myRoundRec()
        local role=type(rec)=="table" and rec.Role and tostring(rec.Role) or nil
        if not role or role=="" then
            local ok,data=pcall(function()return Private.__pulseRoles and Private.__pulseRoles()end)
            local entry=ok and type(data)=="table" and data[LocalPlayer.Name]
            if type(entry)=="table" and entry.Dead~=true and entry.Killed~=true then role=entry.Role and tostring(entry.Role) or nil end
        end
        return role
    end
    local function aliveRound(role)
        if not role or role=="" or farm and farm.inLobbyNow and farm.inLobbyNow() then return false end
        local character=LocalPlayer.Character
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health<=0 then return false end
        local timer=World:FindFirstChild("RoundTimerPart")
        local seconds=timer and tonumber(timer:GetAttribute("Time"))
        return seconds==nil or seconds>0
    end
    local function lobbyCFrame()
        local lobby=World:FindFirstChild("RegularLobby") or World:FindFirstChild("Lobby")
        if not lobby then return nil end
        local spawns=lobby:FindFirstChild("Spawns")
        local point=spawns and spawns:FindFirstChildWhichIsA("BasePart")
        point=point or lobby:FindFirstChildWhichIsA("SpawnLocation",true)
        return point and point.CFrame+Vector3.new(0,4,0) or nil
    end
    local function waitAtLobby()
        local character=LocalPlayer.Character
        local root=character and character:FindFirstChild("HumanoidRootPart")
        local destination=lobbyCFrame()
        if not (root and destination) then return false end
        if (root.Position-destination.Position).Magnitude>=300 then
            pcall(function()
                root.AssemblyLinearVelocity=Vector3.zero
                root.AssemblyAngularVelocity=Vector3.zero
                root.CFrame=destination
            end)
        end
        return true
    end
    local function setKillAll(value)
        if applied.killAll==value then return end
        applied.killAll=value
        if Private.__pulseSetKillAll then pcall(Private.__pulseSetKillAll,value) end
    end
    local function update()
        if not running then return end
        local role=currentRole()
        local live=aliveRound(role)
        local murder=live and role and role:lower():find("murder",1,true)~=nil and (cfg.murderer or cfg.exp)
        local sheriff=live and role=="Sheriff" and (cfg.sheriff or cfg.exp)
        local innocent=live and (role=="Innocent" or role=="Survivor" or role=="Hero") and (cfg.innocent or cfg.exp)
        local roleWinMode=(sheriff and cfg.sheriff) or (innocent and cfg.innocent)
        setKillAll(murder==true)
        _G.__lessRoleFarmHold=roleWinMode==true or nil
        if roleWinMode then
            waitAtLobby()
            if sheriff and os.clock()-lastShot>=0.6 then
                lastShot=os.clock()
                if Private.__pulseShotMurder then pcall(Private.__pulseShotMurder) end
            end
        end
        local mode=cfg.exp and "EXP Farm" or cfg.murderer and "Murderer Kill Farm" or cfg.sheriff and "Sheriff Win Farm" or cfg.innocent and "Innocent Win Farm" or "Waiting"
        local action=murder and "Murderer: Kill All active" or sheriff and "Sheriff: waiting in lobby and shooting at the murderer" or innocent and "Innocent: waiting safely in the lobby" or "Waiting for a matching live role"
        if statusLabel then statusLabel.Text="Mode: "..mode.."  |  Role: "..tostring(role or "Waiting").."  |  "..action end
    end
    local function stop()
        running=false
        _G.__lessRoleFarmHold=nil
        setKillAll(false)
    end
    tab:Header("Role Farm — Less")
    tab:Note({Text="Innocent mode moves you to the lobby to survive until the round ends. Sheriff mode waits there and tries to shoot the murderer. Both pause coin farming while active."})
    local master=tab:Toggle({Text="Enable Role Farm",NoSave=true,Default=false,Callback=function(value)
        running=value
        if value then update() else stop() end
    end})
    tab:Toggle({Text="Innocent Win Farm",Default=cfg.innocent,Callback=function(value)cfg.innocent=value;update()end})
    tab:Toggle({Text="Sheriff Win Farm",Default=cfg.sheriff,Callback=function(value)cfg.sheriff=value;update()end})
    tab:Toggle({Text="Murderer Kill Farm",Default=cfg.murderer,Callback=function(value)cfg.murderer=value;update()end})
    tab:Toggle({Text="EXP Farm",Default=cfg.exp,Callback=function(value)cfg.exp=value;update()end})
    statusLabel=tab:Note({Text="Role Farm: disabled"})
    local elapsed=0
    Connect(RunService.Heartbeat,function(dt)
        elapsed+=dt
        if elapsed>=0.25 then elapsed=0;if running then update() elseif statusLabel then statusLabel.Text="Role Farm: disabled" end end
    end)
    OnCleanup(stop)
    Private.LessRoleFarm={Update=update,Stop=stop,Config=cfg}
end

do
    local tab=UI:Tab("Halloween","ghost")
    settings.mapVote=settings.mapVote or {favorite="",panel=true}
    local cfg=settings.mapVote
    if cfg.panel==nil then cfg.panel=true end
    tab:Header("Map Vote Assistant")
    cfg.repeatCount=math.clamp(math.floor(tonumber(cfg.repeatCount)or 2),1,10)
    tab:Note({Text="Shows the three map pads. Set the number of votes to request; MM2 requires a respawn between accepted votes. The sequence stops if a vote is not counted."})
    local gui=Make("ScreenGui",{Name="LessMapVoteFloat",ResetOnSpawn=false,IgnoreGuiInset=true,DisplayOrder=10020,Enabled=true},Host)
    local panel=Make("Frame",{Name="MapVote",AnchorPoint=Vector2.new(0.5,0),Position=UDim2.new(0.5,0,0,88),Size=UDim2.fromOffset(372,210),BackgroundColor3=Color3.fromHex("1D1227"),BorderSizePixel=0,Visible=false,Active=true},gui)
    Round(panel,12);Stroke(panel,Color3.fromHex("FF8A24"),1.5,0.15)
    local title=Make("TextLabel",{Name="Title",BackgroundTransparency=1,Position=UDim2.fromOffset(12,6),Size=UDim2.new(1,-24,0,24),Font=Enum.Font.GothamBold,TextSize=15,TextXAlignment=Enum.TextXAlignment.Left,TextColor3=Color3.fromHex("FFF1DE"),Text="Halloween · Map Vote"},panel)
    local status=Make("TextLabel",{Name="Status",BackgroundTransparency=1,Position=UDim2.fromOffset(12,31),Size=UDim2.new(1,-24,0,17),Font=Enum.Font.Gotham,TextSize=11,TextXAlignment=Enum.TextXAlignment.Left,TextColor3=Color3.fromHex("CEB4D9"),Text="Waiting for map voting…"},panel)
    local close=Make("TextButton",{Name="Close",AnchorPoint=Vector2.new(1,0),Position=UDim2.new(1,-8,0,7),Size=UDim2.fromOffset(24,22),BackgroundTransparency=1,Text="×",Font=Enum.Font.GothamBold,TextSize=20,TextColor3=Color3.fromHex("FFC06B")},panel)
    Connect(close.Activated,function()cfg.panel=false;panel.Visible=false end)
    local cards={}
    local selected=1
    local voteLobby,lastLobbyScan=nil,-math.huge
    local voteBusy,voteStop=false,false
    local function hasVotePads(object)
        if not object then return false end
        local pad1=object:FindFirstChild("VotePad1",true) or object:FindFirstChild("MapVotePad1",true)
        local pad2=object:FindFirstChild("VotePad2",true) or object:FindFirstChild("MapVotePad2",true)
        local pad3=object:FindFirstChild("VotePad3",true) or object:FindFirstChild("MapVotePad3",true)
        if not (pad1 and pad2 and pad3) then return false end
        local pads=object:FindFirstChild("VotePads",true) or object:FindFirstChild("MapVotePads",true)
        if pads then return true end
        return pad1:FindFirstChild("Pad",true)~=nil and pad2:FindFirstChild("Pad",true)~=nil and pad3:FindFirstChild("Pad",true)~=nil
    end
    local function findLobby()
        if voteLobby and voteLobby.Parent and hasVotePads(voteLobby) then return voteLobby end
        if os.clock()-lastLobbyScan<1 then return nil end
        lastLobbyScan=os.clock()
        local regular=World:FindFirstChild("RegularLobby",true)
        if hasVotePads(regular) then voteLobby=regular;return regular end
        -- Event lobbies are often renamed; identify them by their vote-pad structure.
        for _,object in ipairs(World:GetDescendants())do
            if (object.Name=="VotePads" or object.Name=="MapVotePads") and hasVotePads(object.Parent) then
                voteLobby=object.Parent;return voteLobby
            end
        end
        for _,object in ipairs(World:GetDescendants())do
            local name=object.Name:lower()
            if name=="votepad1" or name=="mapvotepad1" then
                local candidate=object.Parent
                for _=1,8 do
                    if not candidate then break end
                    if hasVotePads(candidate) then voteLobby=candidate;return voteLobby end
                    candidate=candidate.Parent
                end
            end
        end
        voteLobby=nil
    end
    local function readMap(index)
        local lobby=findLobby();if not lobby then return end
        local pad=lobby:FindFirstChild("VotePad"..index,true) or lobby:FindFirstChild("MapVotePad"..index,true)
        local detectors=lobby:FindFirstChild("VotePads",true) or lobby:FindFirstChild("MapVotePads",true)
        local detector=detectors and (detectors:FindFirstChild("Detector"..index,true) or detectors:FindFirstChild("MapVoteDetector"..index,true)) or pad and pad:FindFirstChild("Pad",true)
        if not pad or not detector or not detector:IsA("BasePart") then return end
        local name,votes,icon,mode="MAP NAME",0,"",""
        pcall(function()local voteInfo=pad:FindFirstChild("VoteInfoGui",true);local info=voteInfo and voteInfo:FindFirstChild("Container",true);local mapName=info and info:FindFirstChild("MapName",true);local voteCount=info and info:FindFirstChild("Votes",true);name=mapName and mapName.Text or name;votes=tonumber(tostring(voteCount and voteCount.Text or ""):match("%d+"))or 0 end)
        pcall(function()local mapInfo=pad:FindFirstChild("MapInfoGui",true);local mapIcon=mapInfo and mapInfo:FindFirstChild("MapIcon",true);local gameMode=mapInfo and mapInfo:FindFirstChild("GameMode",true);icon=mapIcon and mapIcon.Image or "";mode=gameMode and gameMode.Text or "" end)
        return {name=name,votes=votes,icon=icon,mode=mode,detector=detector,active=(name~="" and name~="MAP NAME") or icon~=""}
    end
    local function vote(index)
        if voteBusy then Notify("A vote sequence is already running.","Map Vote");return end
        local map=readMap(index)
        if not map or not map.active then Notify("That map is not available to vote for.","Map Vote");return end
        local character=LocalPlayer.Character;local root=character and character:FindFirstChild("HumanoidRootPart");local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        if not root or not humanoid or humanoid.Health<=0 then Notify("You need a living character to vote.","Map Vote");return end
        selected=index;cfg.favorite=map.name;voteBusy=true;voteStop=false
        local wanted=math.clamp(math.floor(tonumber(cfg.repeatCount)or 1),1,10)
        task.spawn(function()
            local completed,reason=0,nil
            for attempt=1,wanted do
                if voteStop then reason="Stopped.";break end
                local current=readMap(index)
                if not current or not current.active then reason="Voting ended.";break end
                character=LocalPlayer.Character;root=character and character:FindFirstChild("HumanoidRootPart");humanoid=character and character:FindFirstChildOfClass("Humanoid")
                if not root or not humanoid or humanoid.Health<=0 then reason="Waiting for a living character.";break end
                local before=current.votes
                root.CFrame=CFrame.new(current.detector.Position-Vector3.new(0,1.2,0))*(root.CFrame-root.CFrame.Position)
                status.Text=string.format("Voting for %s · %d/%d",current.name,attempt,wanted)
                local deadline=os.clock()+1.5
                local counted=false
                while os.clock()<deadline and not voteStop do
                    local updated=readMap(index)
                    if not updated or not updated.active then reason="Voting ended.";break end
                    if updated.votes>before then counted=true;break end
                    RunService.Heartbeat:Wait()
                end
                if not counted then reason=voteStop and "Stopped." or "MM2 did not register the vote; sequence stopped.";break end
                completed+=1
                if attempt<wanted and not voteStop then
                    status.Text=string.format("Vote %d/%d counted · waiting for respawn",completed,wanted)
                    local oldCharacter=character
                    pcall(function()humanoid.Health=0 end)
                    local deadlineRespawn=os.clock()+15
                    repeat
                        RunService.Heartbeat:Wait()
                        character=LocalPlayer.Character
                        root=character and character:FindFirstChild("HumanoidRootPart")
                        humanoid=character and character:FindFirstChildOfClass("Humanoid")
                    until voteStop or (character and character~=oldCharacter and root and humanoid and humanoid.Health>0) or os.clock()>=deadlineRespawn
                    if not character or character==oldCharacter or not root or not humanoid or humanoid.Health<=0 then reason=voteStop and "Stopped." or "Respawn did not complete; sequence stopped.";break end
                end
            end
            voteBusy=false
            status.Text=string.format("%d/%d votes counted for %s%s",completed,wanted,map.name,reason and (" · "..reason)or"")
        end)
    end
    for index=1,3 do
        local card=Make("TextButton",{Name="Map"..index,Position=UDim2.fromOffset(10+(index-1)*118,58),Size=UDim2.fromOffset(112,136),BackgroundColor3=Color3.fromHex("321D3D"),BorderSizePixel=0,Text="",AutoButtonColor=true,Visible=false},panel)
        Round(card,9);local outline=Stroke(card,Color3.fromHex("633765"),1,0.1)
        local image=Make("ImageLabel",{Name="MapImage",Position=UDim2.fromOffset(5,5),Size=UDim2.new(1,-10,0,74),BackgroundColor3=Color3.fromHex("160E20"),BorderSizePixel=0,Image="",ScaleType=Enum.ScaleType.Crop},card);Round(image,6)
        local name=Make("TextLabel",{Name="MapName",Position=UDim2.fromOffset(5,83),Size=UDim2.new(1,-10,0,28),BackgroundTransparency=1,Text="—",TextWrapped=true,Font=Enum.Font.GothamBold,TextSize=12,TextColor3=Color3.fromHex("FFF1DE")},card)
        local details=Make("TextLabel",{Name="Votes",Position=UDim2.fromOffset(5,112),Size=UDim2.new(1,-10,0,17),BackgroundTransparency=1,Text="",Font=Enum.Font.Gotham,TextSize=10,TextColor3=Color3.fromHex("FFC06B")},card)
        cards[index]={frame=card,stroke=outline,image=image,name=name,details=details}
        Connect(card.Activated,function()vote(index)end)
    end
    local dragging,dragAt,panelAt=false,nil,nil
    Connect(title.InputBegan,function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=true;dragAt=input.Position;panelAt=panel.Position end
    end)
    Connect(Input.InputChanged,function(input)
        if not dragging then return end
        if input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch then
            local delta=input.Position-dragAt;panel.Position=UDim2.new(panelAt.X.Scale,panelAt.X.Offset+delta.X,panelAt.Y.Scale,panelAt.Y.Offset+delta.Y)
        end
    end)
    Connect(Input.InputEnded,function(input)if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=false end end)
    tab:Toggle({Text="Floating Map Vote Panel",Default=cfg.panel,Callback=function(value)cfg.panel=value==true end})
    tab:Slider({Text="Votes to cast",Min=1,Max=10,Default=cfg.repeatCount,Decimals=0,Callback=function(value)cfg.repeatCount=math.clamp(math.floor(tonumber(value)or 1),1,10)end})
    tab:Button({Text="Stop vote sequence",Callback=function()voteStop=true end})
    tab:Button({Text="Show map vote panel",Callback=function()cfg.panel=true;panel.Visible=true end})
    tab:Button({Text="Refresh map choices",Callback=function()
        local count=0;for index=1,3 do local map=readMap(index);if map and map.active then count+=1 end end
        Notify(count>0 and ("Found "..count.." maps in the active lobby vote pads.") or "No active map vote found in the current lobby. Try again when the vote phase begins.","Map Vote")
    end})
    local function roundInProgress()
        local timer=World:FindFirstChild("RoundTimerPart")
        local seconds=timer and tonumber(timer:GetAttribute("Time"))
        return seconds~=nil and seconds>0
    end
    local elapsed=0
    Connect(RunService.Heartbeat,function(dt)
        elapsed+=dt;if elapsed<0.2 then return end;elapsed=0
        local count=0
        for index=1,3 do
            local map=readMap(index);local item=cards[index]
            if map and map.active then
                count+=1;item.frame.Visible=true;item.image.Image=map.icon;item.name.Text=map.name;item.details.Text=tostring(map.votes).." votes"..(map.mode~="" and (" · "..map.mode)or"")
                item.stroke.Color=(index==selected or map.name==cfg.favorite)and Color3.fromHex("FF8A24")or Color3.fromHex("633765")
            else item.frame.Visible=false end
        end
        local inRound=roundInProgress()
        panel.Visible=cfg.panel==true and not inRound
        if not voteBusy then
            if inRound then status.Text="Round in progress · map vote panel hidden."
            elseif count>0 then status.Text="Select a map card to cast your vote."
            elseif cfg.panel then status.Text="Waiting for map voting to open in the active lobby…" end
        end
    end)
    OnCleanup(function()pcall(function()gui:Destroy()end)end)
end


-- Particle-only aura selector. These entries mirror AuraExecutorTest.lua;
-- only ParticleEmitter instances are copied, never source models or scripts.
local Extras = UI:Tab("Halloween", "ghost")
Extras:Group({Title="Aura Library",Side="Left"})
local auraItems={
    {name="Foxfire Ascension",id="104617134238266",heightOffset=-3},
    {name="Obsidian Foxfire",id="104617134238266",heightOffset=-3,black=true},
    {name="Phantom Orbit",id="1093787744",group=1,positionScale=0},
    {name="Spectral Bloom",id="1093787744",group=2,positionScale=0},
    {name="Starfall Mantle",id="1093787744",group=3,positionScale=0},
    {name="Wraithfire Crown",id="1093787744",group=4,positionScale=0},
    {name="Coreflare Vortex",id="89034737207441",positionScale=0},
    {name="Abyssal Orbit",id="1093787744",group=1,positionScale=0,black=true},
    {name="Eclipse Bloom",id="1093787744",group=2,positionScale=0,black=true},
    {name="Blackstar Mantle",id="1093787744",group=3,positionScale=0,black=true},
    {name="Nocturne Crown",id="1093787744",group=4,positionScale=0,black=true},
}
settings.localAura=settings.localAura or {on=false,name="Foxfire Ascension",size=1,height=-2}
local aura=settings.localAura
if aura.on==nil then aura.on=false end
if aura.size==nil then aura.size=1 end
if aura.height==nil then aura.height=-2 end
local auraObjects,auraRoot={},nil
local auraTemplates={}
local function clearAura()
    for _,object in ipairs(auraObjects)do pcall(function()object:Destroy()end)end
    auraObjects={};auraRoot=nil
end
local function auraSource(item)
    if auraTemplates[item.id] and auraTemplates[item.id].Parent==nil then return auraTemplates[item.id] end
    local ok,assets=pcall(function()return game:GetObjects("rbxassetid://"..item.id)end)
    if not ok or type(assets)~="table" or #assets==0 then return nil end
    local source=assets[1]
    auraTemplates[item.id]=source
    for index=2,#assets do pcall(function()assets[index]:Destroy()end)end
    return source
end
local function auraPivot(source)
    if source:IsA("Model")then return source:GetPivot()end
    if source:IsA("BasePart")then return source.CFrame end
    local part=source:FindFirstChildWhichIsA("BasePart",true)
    return part and part.CFrame or nil
end
local function auraBranch(source,object)
    local branch=object
    while branch and branch.Parent~=source do branch=branch.Parent end
    return branch
end
local function buildAura()
    clearAura()
    if not aura.on then return end
    local root=Root();if not root then return end
    local selected
    for _,item in ipairs(auraItems)do if item.name==aura.name then selected=item;break end end
    selected=selected or auraItems[1];aura.name=selected.name
    local source=auraSource(selected)
    if not source then Notify("Could not load aura asset "..selected.id,"Halloween Auras");return end
    local pivot=auraPivot(source)
    if not pivot then Notify("Aura asset has no emitter source part.","Halloween Auras");return end
    local branchList
    if selected.group then
        branchList={}
        for _,child in ipairs(source:GetChildren())do
            local hasEmitter=false
            for _,descendant in ipairs(child:GetDescendants())do
                if descendant:IsA("ParticleEmitter")then hasEmitter=true;break end
            end
            if hasEmitter then branchList[#branchList+1]=child end
        end
        if not branchList[selected.group]then Notify("Could not isolate this aura group in the asset.","Halloween Auras");return end
    end
    local count=0
    for _,object in ipairs(source:GetDescendants())do
        local inGroup=not selected.group or auraBranch(source,object)==branchList[selected.group]
        if object:IsA("ParticleEmitter") and inGroup and count<24 then
            local parent=object.Parent
            local sourceFrame
            if parent:IsA("Attachment") and parent.Parent and parent.Parent:IsA("BasePart")then
                sourceFrame=parent.Parent.CFrame*parent.CFrame
            elseif parent:IsA("BasePart")then sourceFrame=parent.CFrame end
            if sourceFrame then
                local localFrame=pivot:ToObjectSpace(sourceFrame)
                local positionScale=selected.positionScale
                if positionScale==nil then positionScale=1.35 end
                local heightOffset=selected.heightOffset
                if heightOffset==nil then heightOffset=aura.height end
                local p=localFrame.Position
                local scaledPosition=Vector3.new(p.X*positionScale*aura.size,p.Y*positionScale*aura.size+heightOffset,p.Z*positionScale*aura.size)
                local attachment=Make("Attachment",{
                    Name="LessNovaAssetAuraAttachment",
                    CFrame=CFrame.new(scaledPosition)*localFrame.Rotation,
                },root)
                auraObjects[#auraObjects+1]=attachment
                local emitter=object:Clone()
                emitter.Enabled=true
                emitter:SetAttribute("LessNovaAura",true)
                local scaledSize={}
                for _,keypoint in ipairs(emitter.Size.Keypoints)do
                    scaledSize[#scaledSize+1]=NumberSequenceKeypoint.new(keypoint.Time,keypoint.Value*aura.size,keypoint.Envelope*aura.size)
                end
                emitter.Size=NumberSequence.new(scaledSize)
                if selected.black then
                    emitter.Color=ColorSequence.new(Color3.fromRGB(8,8,10))
                    emitter.LightInfluence=0
                    emitter.LightEmission=0
                end
                emitter.Parent=attachment
                auraObjects[#auraObjects+1]=emitter
                count+=1
            end
        end
    end
    if count==0 then clearAura();Notify("No usable ParticleEmitters were found in this asset.","Halloween Auras");return end
    auraRoot=root
end
Private.__pulseVFXMine=function()return aura.on and auraObjects or nil end
Extras:Toggle({Text="Aura enabled",Default=aura.on,Callback=function(value)aura.on=value==true;buildAura()end})
local auraOptions={}
for _,item in ipairs(auraItems)do auraOptions[#auraOptions+1]={code=item.name,label=item.name}end
Extras:Dropdown({Text="Aura style",Default=aura.name,Options=auraOptions,Callback=function(value)aura.name=value;buildAura()end})
Extras:Group({Title="Aura Placement",Side="Right"})
Extras:Slider({Text="Size",Min=0.5,Max=3,Decimals=1,Default=aura.size,Callback=function(value)aura.size=value;buildAura()end})
Extras:Slider({Text="Height",Min=-5,Max=2,Decimals=1,Default=aura.height,Callback=function(value)aura.height=value;buildAura()end})
Extras:Note({Text="Local particles only · black options recolor the effect."})
Connect(LocalPlayer.CharacterAdded,function(char)
    task.spawn(function()char:WaitForChild("HumanoidRootPart",10);if char==LocalPlayer.Character then buildAura()end end)
end)
Connect(RunService.Heartbeat,function()if aura.on and Root()~=auraRoot then buildAura()end end)
OnCleanup(function()
    clearAura()
    for _,template in pairs(auraTemplates)do pcall(function()template:Destroy()end)end
    auraTemplates={}
end)
config.applyHooks[#config.applyHooks+1]=buildAura
Private.LessAura={Build=buildAura,Clear=clearAura,Config=aura}

-- Local textures can be supplied by Roblox asset ID without the missing gallery.
Extras:Header("Custom texture pack")
settings.localTexture=settings.localTexture or {on=false,id="",size=8}
local tex=settings.localTexture
local addedTextures=setmetatable({}, {__mode="k"})
local function removeTextures()
    for _,objects in pairs(addedTextures) do for _,object in ipairs(objects) do pcall(function()object:Destroy()end) end end
    addedTextures=setmetatable({}, {__mode="k"})
end
local function texturePart(part)
    if not tex.on or not part:IsA("BasePart") or part:IsA("Terrain") or addedTextures[part] then return end
    if part:IsDescendantOf(LocalPlayer.Character or Window.Gui) or part.Transparency>=1 then return end
    for _,player in ipairs(Players:GetPlayers()) do if player.Character and part:IsDescendantOf(player.Character) then return end end
    if not tex.id:match("%d+") then return end
    local objects={}
    for _,face in ipairs(Enum.NormalId:GetEnumItems()) do
        objects[#objects+1]=Make("Texture",{Name="LessNovaTexture",Texture="rbxassetid://"..tex.id:match("%d+"),Face=face,StudsPerTileU=tex.size,StudsPerTileV=tex.size},part)
    end
    addedTextures[part]=objects
end
local textureGeneration=0
local function rebuildTextures()
    textureGeneration+=1;local generation=textureGeneration;removeTextures()
    if not tex.on then return end
    task.spawn(function()
        for index,object in ipairs(World:GetDescendants()) do
            if generation~=textureGeneration then break end
            texturePart(object);if index%100==0 then task.wait() end
        end
    end)
end
Extras:Input({Text="Texture asset ID",Default=tex.id,Callback=function(value)tex.id=tostring(value):match("%d+") or "";rebuildTextures()end})
Extras:Slider({Text="Texture tile size",Min=1,Max=32,Default=tex.size,Decimals=0,Callback=function(value)tex.size=value;rebuildTextures()end})
Extras:Toggle({Text="Apply custom texture",Default=false,Callback=function(value)tex.on=value;rebuildTextures()end})
Connect(World.DescendantAdded,function(object)if tex.on then guarded("texture",texturePart,object)end end)
OnCleanup(removeTextures)

Combat:Group({Title="Less knife hitbox",Side="Right"})
local hitboxSize,showHitbox,originalKnife=1,false,setmetatable({}, {__mode="k"})
local hitboxSphere=Make("Part",{Name="LessNovaHitboxPreview",Shape=Enum.PartType.Ball,Anchored=true,CanCollide=false,CanTouch=false,CanQuery=false,Material=Enum.Material.ForceField,Color=Color3.fromHex("FF8A24"),Transparency=0.65},World)
hitboxSphere.Parent=nil
local function restoreKnife()
    for part,size in pairs(originalKnife) do if part.Parent then part.Size=size end end
    originalKnife=setmetatable({}, {__mode="k"})
end
Combat:Slider({Text="Knife hitbox",Min=1,Max=30,Default=1,Decimals=0,Callback=function(v)hitboxSize=v;if v==1 then restoreKnife()end end})
Combat:Toggle({Text="Show knife hitbox",Default=false,Callback=function(v)showHitbox=v;hitboxSphere.Parent=v and World or nil end})
local hitboxAt=0
Connect(RunService.Heartbeat,function()
    if os.clock()<hitboxAt then return end;hitboxAt=os.clock()+0.1
    local char=LocalPlayer.Character;local knife=char and char:FindFirstChild("Knife")
    local handle=knife and knife:FindFirstChild("Handle")
    if handle and handle:IsA("BasePart") then
        if not originalKnife[handle] then originalKnife[handle]=handle.Size end
        handle.Size=originalKnife[handle]*Vector3.new(1,1,1+0.1*(hitboxSize-1))
        if showHitbox then hitboxSphere.CFrame=handle.CFrame;hitboxSphere.Size=Vector3.one*(1.5+0.15*(hitboxSize-1)) end
    else hitboxSphere.Parent=nil end
    if showHitbox and handle then hitboxSphere.Parent=World end
end)
OnCleanup(restoreKnife)

Combat:Group({Title="Less crosshair",Side="Left"})
local triggerbot,aimbot,triggerFOV=false,false,24
Combat:Toggle({Text="Triggerbot",Default=false,Callback=function(v)triggerbot=v end})
Combat:Toggle({Text="Camera Aimbot",Default=false,Callback=function(v)aimbot=v end})
Combat:Slider({Text="Trigger radius",Min=5,Max=150,Default=triggerFOV,Decimals=0,Callback=function(v)triggerFOV=v end})
BindRender("LessAim",Enum.RenderPriority.Camera.Value+3,function()
    if not (triggerbot or aimbot) then return end
    local target=rolePlayer("Murderer");if not target or target==LocalPlayer then return end
    local root,cam=Root(target),World.CurrentCamera;if not root or not cam then return end
    if not settings.sheriff.wallbang and not Visible(target,cam.CFrame.Position) then return end
    if aimbot then cam.CFrame=cam.CFrame:Lerp(CFrame.lookAt(cam.CFrame.Position,root.Position),0.22) end
    local projected,onScreen=cam:WorldToViewportPoint(root.Position)
    local mouse=Input:GetMouseLocation()
    if triggerbot and onScreen and (Vector2.new(projected.X,projected.Y)-mouse).Magnitude<=triggerFOV then less.shoot() end
end)

local Keybinds=UI:Tab("Keybinds","keyboard")
Keybinds:Header("Less actions")
local actionKeys={}
local actions={
    ["Shoot murderer"]=function()Private.__pulseShotMurder()end,
    ["Grab gun"]=less.grab,["Throw knife"]=function()Private.__pulseThrowKnife()end,
    ["Toggle fly"]=function()settings.fly.on=not settings.fly.on end,
    ["Toggle invisibility"]=function()if Private.__pulseSetInvis then Private.__pulseSetInvis(not settings.invis.on)end end,
    ["Toggle noclip"]=function()if Private.__pulseSetNoclip then Private.__pulseSetNoclip(not settings.noclip.on)end end,
    ["Bomb jump"]=function()if Private.__pulseAutoBombJump then Private.__pulseAutoBombJump()end end,
}
for name in pairs(actions) do
    local actionName=name
    Keybinds:Keybind({Text=actionName,Default=nil,Callback=function(key)actionKeys[actionName]=key end})
end
Connect(Input.InputBegan,function(input,processed)
    if processed or Input:GetFocusedTextBox() then return end
    for name,key in pairs(actionKeys) do
        if input.KeyCode==key or input.UserInputType==key then task.spawn(actions[name]) end
    end
end)

Sounds:Header("Custom Roblox audio")
local customAudio=""
Sounds:Input({Text="Audio asset ID",Default="",Callback=function(v)customAudio=tostring(v):match("%d+") or "" end})
local previewSound
Sounds:Button({Text="Preview audio ID",Callback=function()
    if customAudio=="" then Notify("Introduce un ID de audio.");return end
    if previewSound then previewSound:Destroy() end
    previewSound=Make("Sound",{SoundId="rbxassetid://"..customAudio,Volume=0.6},Services.SoundService)
    previewSound:Play();task.delay(15,function()if previewSound then previewSound:Stop()end end)
end})
Sounds:Button({Text="Stop audio preview",Callback=function()if previewSound then previewSound:Stop()end end})

