local lastSaved=""
task.spawn(function()
    while alive do
        task.wait(3)
        local ok,snapshot=pcall(function()return Http:JSONEncode({settings=serial(settings),controls=serial(stored)})end)
        if ok and snapshot~=lastSaved and not config.applying then
            local written=saveConfig("autosave");if written then lastSaved=snapshot end
        end
    end
end)
